-- Grammar content enrichment: extra examples (2-3/point) + memory_tip/
-- comparison_note/common_mistake for points missing them (N5: 65 pts,
-- N4: all 117 pts). Idempotent by construction (plain UPDATE by id).

update grammar_points set extra_examples_jp = ARRAY['田中さんの傘はどこですか。','これは私の学校の写真です。']::text[], extra_examples_vi = ARRAY['Cây ô của anh Tanaka ở đâu?','Đây là ảnh trường của tôi.']::text[] where id = '66666666-0000-0000-0000-000000000005';
update grammar_points set extra_examples_jp = ARRAY['ここは病院じゃありません。','田中さんは学生じゃありません。会社員です。']::text[], extra_examples_vi = ARRAY['Đây không phải là bệnh viện.','Anh Tanaka không phải là học sinh. Anh ấy là nhân viên công ty.']::text[] where id = '66666666-0000-0000-0000-000000000004';
update grammar_points set extra_examples_jp = ARRAY['山田さんは先生です。','これはわたしのかばんです。']::text[], extra_examples_vi = ARRAY['Anh Yamada là giáo viên.','Đây là cái cặp của tôi.']::text[] where id = '66666666-0000-0000-0000-000000000001';
update grammar_points set extra_examples_jp = ARRAY['あなたは学生ですか。','これはあなたの本ですか。']::text[], extra_examples_vi = ARRAY['Bạn là học sinh phải không?','Đây là sách của bạn phải không?']::text[] where id = '66666666-0000-0000-0000-000000000002';
update grammar_points set extra_examples_jp = ARRAY['田中さんも医者です。','これも私のペンです。']::text[], extra_examples_vi = ARRAY['Anh Tanaka cũng là bác sĩ.','Cái này cũng là bút của tôi.']::text[] where id = '66666666-0000-0000-0000-000000000003';
update grammar_points set extra_examples_jp = ARRAY['私は毎朝コーヒーを飲みます。','東京は日本の首都です。']::text[], extra_examples_vi = ARRAY['Buổi sáng tôi uống cà phê.','Tokyo là thủ đô của Nhật Bản.']::text[], memory_tip = 'は đọc là "wa" khi làm trợ từ, dù viết bằng chữ は (giống chữ "ha").', comparison_note = 'Khác 「が」thường dùng để giới thiệu thông tin MỚI hoặc nhấn mạnh chủ ngữ, còn 「は」nêu chủ đề đã biết.', common_mistake = 'Viết は nhưng đọc nhầm thành "ha" thay vì "wa" khi nó đóng vai trò trợ từ.' where id = 'babe69ed-5246-58e4-a036-37d405ce7243';
update grammar_points set extra_examples_jp = ARRAY['兄は医者です。姉も医者です。','きのうは雨でした。今日も雨です。']::text[], extra_examples_vi = ARRAY['Anh trai tôi là bác sĩ. Chị gái tôi cũng là bác sĩ.','Hôm qua trời mưa. Hôm nay cũng mưa.']::text[], memory_tip = 'も thay thế hoàn toàn cho は/が đứng ngay sau danh từ, không dùng chung với 2 trợ từ đó.', comparison_note = 'Khác N1もN2も (lặp lại も ở cả 2 danh từ) — ở đây も chỉ xuất hiện 1 lần khi so sánh với câu trước.', common_mistake = 'Dùng は và も cùng lúc trong 1 câu (chỉ được chọn 1 trong 2).' where id = '34273e89-35e5-5387-a92c-b96dd5217ae0';
update grammar_points set extra_examples_jp = ARRAY['あれは山田さんの車です。','あの人は先生です。']::text[], extra_examples_vi = ARRAY['Kia là xe ô tô của anh Yamada.','Người kia là giáo viên.']::text[] where id = '66666666-0000-0000-0000-000000000006';
update grammar_points set extra_examples_jp = ARRAY['それは中国のお茶です。','この時計はスイスの時計です。']::text[], extra_examples_vi = ARRAY['Đó là trà của Trung Quốc.','Cái đồng hồ này là đồng hồ của Thụy Sĩ.']::text[] where id = '66666666-0000-0000-0000-000000000008';
update grammar_points set extra_examples_jp = ARRAY['田中さんはあそこにいます。','こちらは山田さんです。']::text[], extra_examples_vi = ARRAY['Anh Tanaka ở đằng kia.','Đây là anh Yamada.']::text[] where id = '66666666-0000-0000-0000-000000000007';
update grammar_points set extra_examples_jp = ARRAY['これはあなたのかばんですか。いいえ、そうじゃありません。','田中さんは先生ですか。はい、そうです。']::text[], extra_examples_vi = ARRAY['Đây là cặp của bạn à? Không, không phải vậy.','Anh Tanaka là giáo viên phải không? Vâng, đúng vậy.']::text[] where id = '66666666-0000-0000-0000-000000000009';
update grammar_points set extra_examples_jp = ARRAY['どうもすみません。','どうも、お元気ですか。']::text[], extra_examples_vi = ARRAY['Xin lỗi anh/chị rất nhiều.','Chào anh/chị, anh/chị khỏe không?']::text[] where id = '66666666-0000-0000-0000-000000000012';
update grammar_points set extra_examples_jp = ARRAY['このかばんはいくらですか。三千円です。','全部でいくらですか。']::text[], extra_examples_vi = ARRAY['Cái cặp này bao nhiêu tiền? Ba nghìn yên.','Tất cả bao nhiêu tiền?']::text[] where id = '66666666-0000-0000-0000-000000000010';
update grammar_points set extra_examples_jp = ARRAY['コーヒーを一つください。','この赤いシャツをください。']::text[], extra_examples_vi = ARRAY['Cho tôi một cốc cà phê.','Cho tôi cái áo sơ mi màu đỏ này.']::text[] where id = '66666666-0000-0000-0000-000000000011';
update grammar_points set extra_examples_jp = ARRAY['冷蔵庫の中に卵があります。','公園に子供たちがいます。']::text[], extra_examples_vi = ARRAY['Trong tủ lạnh có trứng.','Trong công viên có các em nhỏ.']::text[] where id = '66666666-0000-0000-0000-000000000014';
update grammar_points set extra_examples_jp = ARRAY['りんごもみかんもあります。','兄も弟も学生です。']::text[], extra_examples_vi = ARRAY['Có cả táo và cam.','Cả anh trai và em trai đều là học sinh.']::text[] where id = '66666666-0000-0000-0000-000000000016';
update grammar_points set extra_examples_jp = ARRAY['つくえの上にペンや消しゴムがあります。','冷蔵庫に牛乳やジュースがあります。']::text[], extra_examples_vi = ARRAY['Trên bàn có bút, tẩy và vài thứ khác.','Trong tủ lạnh có sữa, nước ép và vài thứ khác.']::text[] where id = '66666666-0000-0000-0000-000000000017';
update grammar_points set extra_examples_jp = ARRAY['部屋にテレビがあります。','庭に木があります。']::text[], extra_examples_vi = ARRAY['Trong phòng có ti vi.','Trong sân có cây.']::text[], memory_tip = 'があります dùng cho đồ vật, cây cối — những thứ KHÔNG tự di chuyển được.', comparison_note = 'Khác ～がいます (dùng cho người, động vật — những thứ có thể tự di chuyển).', common_mistake = 'Dùng があります cho người hoặc động vật (phải dùng がいます).' where id = '0661ae4e-8e39-5a41-86f9-1488b6629228';
update grammar_points set extra_examples_jp = ARRAY['庭に犬がいます。','教室に先生がいます。']::text[], extra_examples_vi = ARRAY['Trong sân có một con chó.','Trong lớp học có giáo viên.']::text[], memory_tip = 'がいます dùng cho người và động vật — những thứ tự di chuyển được.', comparison_note = 'Khác ～があります (dùng cho đồ vật, cây cối — những thứ KHÔNG tự di chuyển).', common_mistake = 'Dùng がいます cho đồ vật vô tri (phải dùng があります).' where id = 'f085451d-8485-5250-9c5a-d1c17ee79065';
update grammar_points set extra_examples_jp = ARRAY['机の上に本があります。いすに猫がいます。','冷蔵庫に何がありますか。']::text[], extra_examples_vi = ARRAY['Trên bàn có sách. Trên ghế có con mèo.','Trong tủ lạnh có gì?']::text[] where id = '66666666-0000-0000-0000-000000000015';
update grammar_points set extra_examples_jp = ARRAY['そこにかさがあります。','あそこに学生がいます。']::text[], extra_examples_vi = ARRAY['Ở đó có cây ô.','Ở đằng kia có học sinh.']::text[] where id = '66666666-0000-0000-0000-000000000013';
update grammar_points set extra_examples_jp = ARRAY['教室にだれもいません。','冷蔵庫に何もありません。']::text[], extra_examples_vi = ARRAY['Trong lớp học không có ai cả.','Trong tủ lạnh không có gì cả.']::text[] where id = '66666666-0000-0000-0000-000000000018';
update grammar_points set extra_examples_jp = ARRAY['父と母は元気です。','パンとたまごを食べました。']::text[], extra_examples_vi = ARRAY['Bố và mẹ tôi khỏe.','Tôi đã ăn bánh mì và trứng.']::text[] where id = '66666666-0000-0000-0000-000000000021';
update grammar_points set extra_examples_jp = ARRAY['月曜日から金曜日まで働きます。','家から駅まで十分です。']::text[], extra_examples_vi = ARRAY['Tôi làm việc từ thứ Hai đến thứ Sáu.','Từ nhà đến ga mất mười phút.']::text[], memory_tip = 'から = điểm bắt đầu (như "từ"), まで = điểm kết thúc (như "đến") — hay đi theo cặp nhưng vẫn có thể tách riêng.', comparison_note = 'Khác ～から (lý do) — cùng chữ から nhưng đứng sau danh từ thời gian/nơi chốn thì mang nghĩa "từ", đứng sau cả câu thì mang nghĩa "vì".', common_mistake = 'Dùng cả から và まで dù câu chỉ cần 1 trong 2 (ví dụ chỉ muốn nói "đến 5 giờ" thì không cần から).' where id = '67144ddd-3226-5a16-988d-bf58ab714369';
update grammar_points set extra_examples_jp = ARRAY['朝ごはんにパンと牛乳を食べます。','かばんの中にノートと辞書があります。']::text[], extra_examples_vi = ARRAY['Bữa sáng tôi ăn bánh mì và uống sữa.','Trong cặp có vở và từ điển.']::text[], memory_tip = 'と nối 2 (hay nhiều) danh từ với nghĩa "và", luôn đứng GIỮA 2 danh từ.', comparison_note = 'Khác や (chỉ liệt kê một phần, ngầm hiểu còn thứ khác) — と liệt kê đầy đủ, không thiếu.', common_mistake = 'Dùng と để nối động từ hoặc tính từ (と chỉ nối DANH TỪ với danh từ).' where id = 'a1b2c3d4-0000-4000-8000-000000000009';
update grammar_points set extra_examples_jp = ARRAY['十二時に昼ごはんを食べます。','月曜日に会社へ行きます。']::text[], extra_examples_vi = ARRAY['Tôi ăn trưa lúc 12 giờ.','Thứ Hai tôi đi đến công ty.']::text[], memory_tip = 'に đi sau danh từ thời gian CÓ SỐ (giờ, ngày, tháng, năm) — riêng thứ trong tuần thì có thể có hoặc không.', comparison_note = 'Khác ～へ (chỉ hướng di chuyển) — に ở đây đánh dấu THỜI ĐIỂM xảy ra hành động.', common_mistake = 'Thêm に sau danh từ thời gian không có số như 今日/明日/毎日 (những từ này KHÔNG cần に).' where id = '87f83460-102a-520f-a922-4477efbf4c04';
update grammar_points set extra_examples_jp = ARRAY['今何時ですか。三時十分です。','すみません、今何時ですか。']::text[], extra_examples_vi = ARRAY['Bây giờ là mấy giờ? Ba giờ mười phút.','Xin lỗi, bây giờ là mấy giờ ạ?']::text[] where id = '66666666-0000-0000-0000-000000000019';
update grammar_points set extra_examples_jp = ARRAY['テストはいつですか。来週の月曜日です。','夏休みはいつからいつまでですか。']::text[], extra_examples_vi = ARRAY['Bài kiểm tra khi nào vậy? Là thứ Hai tuần sau.','Kỳ nghỉ hè từ khi nào đến khi nào vậy?']::text[] where id = '66666666-0000-0000-0000-000000000022';
update grammar_points set extra_examples_jp = ARRAY['図書館は九時から七時までです。','ここから駅まで歩きます。']::text[], extra_examples_vi = ARRAY['Thư viện mở cửa từ 9 giờ đến 7 giờ.','Từ đây tôi đi bộ đến ga.']::text[] where id = '66666666-0000-0000-0000-000000000020';
update grammar_points set extra_examples_jp = ARRAY['このケーキ、おいしいですね。','あぶないですよ。気をつけてください。']::text[], extra_examples_vi = ARRAY['Cái bánh này ngon nhỉ.','Nguy hiểm đấy. Hãy cẩn thận nhé.']::text[] where id = '66666666-0000-0000-0000-000000000023';
update grammar_points set extra_examples_jp = ARRAY['毎朝、公園へ行きます。','友達が私の家へ来ます。']::text[], extra_examples_vi = ARRAY['Mỗi sáng tôi đi đến công viên.','Bạn tôi đến nhà tôi.']::text[] where id = '66666666-0000-0000-0000-000000000024';
update grammar_points set extra_examples_jp = ARRAY['家族と旅行します。','明日、山田さんと映画を見ます。']::text[], extra_examples_vi = ARRAY['Tôi đi du lịch cùng gia đình.','Ngày mai tôi xem phim cùng anh Yamada.']::text[], memory_tip = 'と ở đây đánh dấu người CÙNG thực hiện hành động, khác と nối danh từ với nghĩa "và".', comparison_note = 'Khác N と N (nối 2 danh từ thành "và") — と ở mẫu này đứng sau 1 người, nghĩa là "cùng với".', common_mistake = 'Dùng と cho hành động làm một mình (phải dùng 一人で, không dùng と).' where id = '05a684f6-6077-5c98-a6ad-d559f88c1cf6';
update grammar_points set extra_examples_jp = ARRAY['来年、アメリカへ留学します。','図書館に行きます。']::text[], extra_examples_vi = ARRAY['Sang năm tôi sẽ đi du học ở Mỹ.','Tôi đi đến thư viện.']::text[], memory_tip = 'に nhấn mạnh ĐIỂM ĐẾN cụ thể, へ nhấn mạnh HƯỚNG di chuyển — nhiều trường hợp dùng thay nhau được.', comparison_note = 'Khác N(nơi chốn)に N(vật/người)が あります／います — に ở đó chỉ VỊ TRÍ tồn tại, còn ở đây に/へ chỉ HƯỚNG di chuyển.', common_mistake = 'Dùng へ để chỉ thời điểm (へ chỉ dùng cho hướng/nơi chốn, không dùng cho thời gian).' where id = '836c10ff-b3f1-52d5-9dc5-404e0ffd93e2';
update grammar_points set extra_examples_jp = ARRAY['デパートへ買い物に行きます。','友達の家へ遊びに来ました。']::text[], extra_examples_vi = ARRAY['Tôi đi đến trung tâm thương mại để mua sắm.','Tôi đã đến nhà bạn để chơi.']::text[], memory_tip = 'Động từ thể ます (bỏ ます) + に + 行きます/来ます = đi/đến để làm gì.', comparison_note = 'Khác Vて-form nối hành động liên tiếp — に ở đây chỉ nêu MỤC ĐÍCH của việc đi/đến, không nối 2 hành động ngang hàng.', common_mistake = 'Chia sai thể của động từ mục đích (phải dùng thể ます bỏ ます, ví dụ 見ます→見に, không phải 見て/見る).' where id = 'eb63ca7d-33f3-5614-89c5-1ccdd32fae7c';
update grammar_points set extra_examples_jp = ARRAY['だれと旅行しますか。家族と行きます。','一人でレストランへ行きます。']::text[], extra_examples_vi = ARRAY['Bạn đi du lịch với ai? Tôi đi cùng gia đình.','Tôi đi đến nhà hàng một mình.']::text[] where id = '66666666-0000-0000-0000-000000000027';
update grammar_points set extra_examples_jp = ARRAY['日曜日はどこへも行きませんでした。','今日はどこも行きたくないです。']::text[], extra_examples_vi = ARRAY['Chủ nhật tôi đã không đi đâu cả.','Hôm nay tôi không muốn đi đâu cả.']::text[] where id = '66666666-0000-0000-0000-000000000025';
update grammar_points set extra_examples_jp = ARRAY['宿題はもうしましたか。はい、もうしました。','ご飯はもう食べましたか。いいえ、まだ食べていません。']::text[], extra_examples_vi = ARRAY['Bài tập về nhà làm xong chưa? Vâng, làm xong rồi.','Cơm ăn chưa? Chưa, tôi vẫn chưa ăn.']::text[] where id = '66666666-0000-0000-0000-000000000028';
update grammar_points set extra_examples_jp = ARRAY['学校まで何で行きますか。バスで行きます。','会社まで自転車で行きます。']::text[], extra_examples_vi = ARRAY['Bạn đến trường bằng gì? Tôi đi bằng xe buýt.','Tôi đi đến công ty bằng xe đạp.']::text[] where id = '66666666-0000-0000-0000-000000000026';
update grammar_points set extra_examples_jp = ARRAY['毎日新聞を読みます。','音楽を聞きます。']::text[], extra_examples_vi = ARRAY['Mỗi ngày tôi đọc báo.','Tôi nghe nhạc.']::text[] where id = '66666666-0000-0000-0000-000000000029';
update grammar_points set extra_examples_jp = ARRAY['一緒にお昼を食べましょう。','荷物を持ちましょうか。']::text[], extra_examples_vi = ARRAY['Chúng ta cùng ăn trưa nhé.','Để tôi mang hành lý giúp nhé?']::text[] where id = '66666666-0000-0000-0000-000000000032';
update grammar_points set extra_examples_jp = ARRAY['週末、公園を散歩しませんか。','コーヒーを飲みませんか。']::text[], extra_examples_vi = ARRAY['Cuối tuần, mình đi dạo công viên không?','Uống cà phê không?']::text[] where id = '66666666-0000-0000-0000-000000000031';
update grammar_points set extra_examples_jp = ARRAY['一緒に頑張りましょう。','そろそろ帰りましょう。']::text[], extra_examples_vi = ARRAY['Cùng nhau cố gắng nhé.','Đã đến lúc rồi, về thôi.']::text[], memory_tip = 'ましょう giống "Let''s..." trong tiếng Anh — luôn có ý RỦ cùng làm, không phải ra lệnh.', comparison_note = 'Khác Vませんか (mời, để ngỏ cho đối phương từ chối) — Vましょう chủ động rủ rê, ngữ khí quyết đoán hơn.', common_mistake = 'Dùng Vましょう với người trên (cấp trên, người lớn tuổi) — dễ nghe như ra lệnh, nên dùng Vませんか cho lịch sự hơn.' where id = 'b1a4cdef-7402-5f4c-b14d-762aeedda1df';
update grammar_points set extra_examples_jp = ARRAY['明日、一緒に勉強しませんか。','お茶を飲みに行きませんか。']::text[], extra_examples_vi = ARRAY['Ngày mai học cùng nhau không?','Đi uống trà không?']::text[], memory_tip = 'Nhớ ませんか = lời mời lịch sự, không phải câu hỏi phủ định thật.', comparison_note = 'Khác Vましょう (chủ động rủ) — Vませんか nhẹ nhàng hơn, để đối phương dễ từ chối.', common_mistake = 'Trả lời phủ định trực tiếp "いいえ" nghe hơi cộc — nên thêm lý do như "すみません、ちょっと..." để từ chối lịch sự.' where id = 'd451bf4b-29a9-5720-8075-d9ea9d2f7e95';
update grammar_points set extra_examples_jp = ARRAY['新聞を読みます。','音楽を聞きます。']::text[], extra_examples_vi = ARRAY['Tôi đọc báo.','Tôi nghe nhạc.']::text[], memory_tip = 'を luôn đứng NGAY SAU danh từ là đối tượng chịu tác động của động từ.', comparison_note = 'Khác は (chủ đề) và が (chủ ngữ) — を chỉ đánh dấu tân ngữ trực tiếp của ngoại động từ.', common_mistake = 'Nhầm を với に khi động từ là 乗ります (lên xe) — 乗ります đi với に, không phải を (バスに乗ります, không phải バスを乗ります).' where id = 'c568bcf9-a602-50e1-b52e-a2a8226210f4';
update grammar_points set extra_examples_jp = ARRAY['ペンで名前を書きます。','日本語で話します。']::text[], extra_examples_vi = ARRAY['Tôi viết tên bằng bút.','Tôi nói bằng tiếng Nhật.']::text[] where id = '66666666-0000-0000-0000-000000000033';
update grammar_points set extra_examples_jp = ARRAY['明日何をしますか。友達に会います。','週末何をしますか。家で休みます。']::text[], extra_examples_vi = ARRAY['Ngày mai bạn làm gì? Tôi gặp bạn.','Cuối tuần bạn làm gì? Tôi nghỉ ở nhà.']::text[] where id = '66666666-0000-0000-0000-000000000030';
update grammar_points set extra_examples_jp = ARRAY['もっと時間がほしいです。','かわいい犬がほしいです。']::text[], extra_examples_vi = ARRAY['Tôi muốn có nhiều thời gian hơn.','Tôi muốn có một con chó dễ thương.']::text[] where id = '66666666-0000-0000-0000-000000000034';
update grammar_points set extra_examples_jp = ARRAY['早く家に帰りたいです。','おいしいラーメンが食べたいです。']::text[], extra_examples_vi = ARRAY['Tôi muốn về nhà sớm.','Tôi muốn ăn ramen ngon.']::text[] where id = '66666666-0000-0000-0000-000000000035';
update grammar_points set extra_examples_jp = ARRAY['新しいスマホがほしいです。','休みがほしいです。']::text[], extra_examples_vi = ARRAY['Tôi muốn có điện thoại thông minh mới.','Tôi muốn có kỳ nghỉ.']::text[], memory_tip = 'ほしい là TÍNH TỪ (đuôi い) diễn tả "muốn có VẬT", luôn đi cùng trợ từ が.', comparison_note = 'Khác Vたいです (muốn LÀM một hành động) — Nがほしいです chỉ dùng khi muốn CÓ một vật/người.', common_mistake = 'Dùng ほしい để mời người nghe dùng thứ gì (sai) — muốn mời phải nói "～はいかがですか", không nói "～がほしいですか".' where id = '2d624cff-6c4e-5027-a47b-957c9a0de43a';
update grammar_points set extra_examples_jp = ARRAY['新しい仕事を始めたいです。','もっと日本語が上手になりたいです。']::text[], extra_examples_vi = ARRAY['Tôi muốn bắt đầu công việc mới.','Tôi muốn giỏi tiếng Nhật hơn.']::text[], memory_tip = 'Bỏ ます, thêm たい vào thân động từ (行きます→行きたい) — chia y hệt tính từ đuôi い.', comparison_note = 'Khác Nがほしいです (muốn CÓ vật) — Vたいです diễn tả muốn LÀM một hành động.', common_mistake = 'Dùng Vたいです để nói về mong muốn của người khác (sai ngữ pháp) — với người thứ ba phải dùng ～たがっています.' where id = '0a6e0bac-ec52-5a3e-9301-81bfd872f6d6';
update grammar_points set extra_examples_jp = ARRAY['会議は3時で終わります。','バスの事故で遅れました。']::text[], extra_examples_vi = ARRAY['Cuộc họp kết thúc lúc 3 giờ.','Tôi đến muộn vì tai nạn xe buýt.']::text[], memory_tip = 'で có nhiều nghĩa (nơi chốn, nguyên nhân, phương tiện, thời hạn) — luôn xét NGỮ CẢNH câu để hiểu đúng nghĩa.', comparison_note = 'Khác で chỉ nơi chốn hành động xảy ra (図書館で勉強します) — ở đây で nhấn mạnh MỐC THỜI GIAN giới hạn hoặc NGUYÊN NHÂN.', common_mistake = 'Nhầm で (nguyên nhân) với から (lý do) — で thường dùng cho nguyên nhân khách quan (tai nạn, thời tiết...), から linh hoạt hơn cho cả lý do chủ quan.' where id = '47485cae-93d4-5387-8367-dabda17d0ddb';
update grammar_points set extra_examples_jp = ARRAY['この料理はとてもおいしいです。','今日はあまり忙しくないです。']::text[], extra_examples_vi = ARRAY['Món ăn này rất ngon.','Hôm nay không bận lắm.']::text[] where id = '66666666-0000-0000-0000-000000000037';
update grammar_points set extra_examples_jp = ARRAY['どうして遅れましたか。電車が遅れたからです。','なぜ日本語を勉強していますか。']::text[], extra_examples_vi = ARRAY['Tại sao bạn đến muộn? Vì tàu điện bị trễ.','Tại sao bạn học tiếng Nhật?']::text[] where id = '66666666-0000-0000-0000-000000000038';
update grammar_points set extra_examples_jp = ARRAY['雨が降っていますから、傘を持って行きます。','疲れましたから、早く寝ます。']::text[], extra_examples_vi = ARRAY['Vì trời đang mưa nên tôi mang theo ô.','Vì mệt nên tôi đi ngủ sớm.']::text[] where id = '66666666-0000-0000-0000-000000000036';
update grammar_points set extra_examples_jp = ARRAY['おいしい料理を食べました。','元気な子供たちですね。']::text[], extra_examples_vi = ARRAY['Tôi đã ăn món ăn ngon.','Những đứa trẻ khỏe mạnh nhỉ.']::text[] where id = '66666666-0000-0000-0000-000000000041';
update grammar_points set extra_examples_jp = ARRAY['この映画はおもしろくないです。','あの店は有名じゃありません。']::text[], extra_examples_vi = ARRAY['Bộ phim này không thú vị.','Cửa hàng đó không nổi tiếng.']::text[] where id = '66666666-0000-0000-0000-000000000042';
update grammar_points set extra_examples_jp = ARRAY['今日は寒いです。','彼の部屋は広いです。']::text[], extra_examples_vi = ARRAY['Hôm nay lạnh.','Phòng của anh ấy rộng.']::text[] where id = '66666666-0000-0000-0000-000000000039';
update grammar_points set extra_examples_jp = ARRAY['彼女はとても親切です。','この問題は簡単です。']::text[], extra_examples_vi = ARRAY['Cô ấy rất tốt bụng.','Vấn đề này đơn giản.']::text[] where id = '66666666-0000-0000-0000-000000000040';
update grammar_points set extra_examples_jp = ARRAY['最近あまり寝ていません。','この店はあまり高くないです。']::text[], extra_examples_vi = ARRAY['Gần đây tôi không ngủ nhiều lắm.','Cửa hàng này không đắt lắm.']::text[], memory_tip = 'あまり luôn đi kèm thể PHỦ ĐỊNH ở cuối câu — thấy あまり mà không có phủ định là sai ngữ pháp.', comparison_note = 'Đối lập với とても (rất, mức độ cao) — あまり~ない diễn tả mức độ thấp (không ~ lắm).', common_mistake = 'Dùng あまり trong câu khẳng định (あまり忙しいです là sai) — phải luôn kết thúc câu bằng dạng phủ định.' where id = '7f7fded5-0305-5f11-9baf-e46c5baf2efa';
update grammar_points set extra_examples_jp = ARRAY['どんな音楽が好きですか。静かな音楽が好きです。','どんな人ですか。優しい人です。']::text[], extra_examples_vi = ARRAY['Bạn thích loại nhạc như thế nào? Tôi thích nhạc nhẹ nhàng.','Anh ấy là người như thế nào? Là người tốt bụng.']::text[] where id = '66666666-0000-0000-0000-000000000043';
update grammar_points set extra_examples_jp = ARRAY['高いですが、質がいいです。','雨が降っていますが、出かけます。']::text[], extra_examples_vi = ARRAY['Tuy đắt nhưng chất lượng tốt.','Tuy trời đang mưa nhưng tôi vẫn ra ngoài.']::text[] where id = '66666666-0000-0000-0000-000000000044';
update grammar_points set extra_examples_jp = ARRAY['買います→買って、行きます→行って、書きます→書いて。','話します→話して、休みます→休んで。']::text[], extra_examples_vi = ARRAY['(mua), (đi), (viết) ở thể て.','(nói chuyện), (nghỉ ngơi) ở thể て.']::text[] where id = '66666666-0000-0000-0000-000000000045';
update grammar_points set extra_examples_jp = ARRAY['大阪に住んでいます。','田中さんはあの学校で英語を教えています。']::text[], extra_examples_vi = ARRAY['Tôi đang sống ở Osaka.','Anh Tanaka dạy tiếng Anh ở trường đó.']::text[] where id = '66666666-0000-0000-0000-000000000047';
update grammar_points set extra_examples_jp = ARRAY['子供が公園で遊んでいます。','母は今、料理を作っています。']::text[], extra_examples_vi = ARRAY['Đứa trẻ đang chơi ở công viên.','Mẹ tôi đang nấu ăn.']::text[] where id = '66666666-0000-0000-0000-000000000046';
update grammar_points set extra_examples_jp = ARRAY['ちょっと待ってください。','窓を開けてください。']::text[], extra_examples_vi = ARRAY['Xin hãy đợi một chút.','Xin hãy mở cửa sổ.']::text[] where id = '66666666-0000-0000-0000-000000000048';
update grammar_points set extra_examples_jp = ARRAY['ここに座ってもいいですか。','教室で食べてはいけません。']::text[], extra_examples_vi = ARRAY['Tôi ngồi đây được không?','Không được ăn trong lớp học.']::text[] where id = '66666666-0000-0000-0000-000000000049';
update grammar_points set extra_examples_jp = ARRAY['ゆっくり話してください。','名前をここに書いてください。']::text[], extra_examples_vi = ARRAY['Xin hãy nói chậm lại.','Xin hãy viết tên vào đây.']::text[], memory_tip = 'Chia động từ về thể て rồi thêm ください là xong — cấu trúc nhờ vả cơ bản nhất.', comparison_note = 'Khác ～を ください (xin một VẬT) — Vてください dùng để nhờ ai làm một HÀNH ĐỘNG.', common_mistake = 'Dùng thẳng Vてください với cấp trên/người lạ mà không thêm すみませんが ở đầu — nghe hơi thẳng, nên thêm để lịch sự hơn.' where id = 'c96bd43c-9d9f-58ea-949a-b326bcad2329';
update grammar_points set extra_examples_jp = ARRAY['廊下を走ってはいけません。','授業中に携帯を使ってはいけません。']::text[], extra_examples_vi = ARRAY['Không được chạy ở hành lang.','Không được dùng điện thoại trong giờ học.']::text[], memory_tip = 'てはいけません = "làm ~ thì không được" — nhớ là CẤM, ngữ khí mạnh hơn てもいいですか.', comparison_note = 'Đối lập trực tiếp với Vてもいいですか (xin phép) — một bên hỏi được không, một bên khẳng định cấm.', common_mistake = 'Dùng てはいけません với người trên mình khi chỉ muốn khuyên nhẹ — nên dùng cách nói giảm nhẹ hơn như ～ないほうがいいです.' where id = 'c6ddf09c-6861-5f34-95d9-f9c60995e946';
update grammar_points set extra_examples_jp = ARRAY['ここで写真を撮ってもいいです。','先に帰ってもいいですよ。']::text[], extra_examples_vi = ARRAY['Ở đây được phép chụp ảnh.','Bạn về trước cũng được đấy.']::text[], memory_tip = 'てもいい = "làm ~ cũng được" — も mang nghĩa "cũng", thể hiện sự cho phép thoải mái.', comparison_note = 'Đối lập với てはいけません (cấm) — cùng dùng thể て nhưng nghĩa hoàn toàn ngược nhau.', common_mistake = 'Khi muốn từ chối lịch sự trước câu hỏi てもいいですか, trả lời thẳng "いいえ" nghe cộc — nên dùng cách nói giảm nhẹ như "ちょっと...".' where id = '3fbc7ac3-af15-5da8-8378-aa33cfca625b';
update grammar_points set extra_examples_jp = ARRAY['母は先生です。山田さんのお母さんも先生です。','兄はサラリーマンです。']::text[], extra_examples_vi = ARRAY['Mẹ tôi là giáo viên. Mẹ chị Yamada cũng là giáo viên.','Anh trai tôi là nhân viên văn phòng.']::text[] where id = '66666666-0000-0000-0000-000000000051';
update grammar_points set extra_examples_jp = ARRAY['教室には学生が三十人います。','この公園には大きい木があります。']::text[], extra_examples_vi = ARRAY['Trong lớp học có ba mươi học sinh.','Trong công viên này có một cây to.']::text[] where id = '66666666-0000-0000-0000-000000000053';
update grammar_points set extra_examples_jp = ARRAY['ご家族は何人ですか。四人家族です。','ご兄弟は何人ですか。二人です。']::text[], extra_examples_vi = ARRAY['Gia đình bạn có mấy người? Gia đình tôi có bốn người.','Bạn có mấy anh chị em? Tôi có hai người.']::text[] where id = '66666666-0000-0000-0000-000000000050';
update grammar_points set extra_examples_jp = ARRAY['教室に学生が一人います。','家族は四人です。']::text[], extra_examples_vi = ARRAY['Trong lớp có một học sinh.','Gia đình có bốn người.']::text[] where id = '66666666-0000-0000-0000-000000000052';
update grammar_points set extra_examples_jp = ARRAY['電車とバスと、どちらが速いですか。','コーヒーと紅茶と、どちらが好きですか。']::text[], extra_examples_vi = ARRAY['Giữa tàu điện và xe buýt, cái nào nhanh hơn?','Giữa cà phê và trà, bạn thích cái nào hơn?']::text[] where id = '66666666-0000-0000-0000-000000000054';
update grammar_points set extra_examples_jp = ARRAY['私は一週間に三回ジムに行きます。','一年に一回旅行します。']::text[], extra_examples_vi = ARRAY['Tôi đi phòng gym ba lần một tuần.','Tôi đi du lịch một lần một năm.']::text[], memory_tip = 'Cấu trúc luôn là [khoảng thời gian]に[số lần]回 — に đứng ngay sau đơn vị thời gian.', comparison_note = 'Khác ～動詞＋数量～ (số lượng đồ vật đặt trước động từ) — ở đây là tần suất theo thời gian, dùng に + 回.', common_mistake = 'Quên trợ từ に sau khoảng thời gian (nói 一週間三回 thay vì 一週間に三回) — thiếu に câu sẽ sai ngữ pháp.' where id = '5a0db655-791b-5d3a-b351-5fdbe3d61d77';
update grammar_points set extra_examples_jp = ARRAY['りんごを三つ食べました。','ビールを二本飲みました。']::text[], extra_examples_vi = ARRAY['Tôi đã ăn ba quả táo.','Tôi đã uống hai chai bia.']::text[], memory_tip = 'Lượng từ (số + đơn vị đếm) đứng NGAY TRƯỚC động từ, không đứng cạnh danh từ như tiếng Việt.', comparison_note = 'Khác ～に~回~ (tần suất theo thời gian) — đây là số lượng đồ vật cho một hành động.', common_mistake = 'Đặt lượng từ ngay sau danh từ kiểu tiếng Việt (みかん4つを thay vì みかんを4つ) — trật tự đúng là Nを + số lượng + V.' where id = 'ef906ac4-a8d6-5c5b-a870-6cab02edfa44';
update grammar_points set extra_examples_jp = ARRAY['私の誕生日は姉と同じです。','このかばんはあれと同じ色です。']::text[], extra_examples_vi = ARRAY['Sinh nhật của tôi trùng với chị gái.','Cái túi này cùng màu với cái kia.']::text[], memory_tip = 'と同じ = "giống với N" — と đánh dấu đối tượng đem ra so sánh.', comparison_note = 'Khác ～より~ (so sánh HƠN KÉM) — と同じ chỉ sự GIỐNG NHAU, không phân định cái nào hơn.', common_mistake = 'Dùng は hoặc が thay vì と trước 同じ khi nêu đối tượng so sánh — phải dùng と để đánh dấu vật đem ra so sánh.' where id = 'eb7676e8-e51c-5262-8d40-3efd974b32b0';
update grammar_points set extra_examples_jp = ARRAY['家族の中で、父が一番背が高いです。','果物の中で、りんごが一番好きです。']::text[], extra_examples_vi = ARRAY['Trong gia đình, bố tôi cao nhất.','Trong các loại trái cây, tôi thích táo nhất.']::text[], memory_tip = 'のなかで = "trong số...", いちばん = "nhất" — luôn cần phạm vi so sánh từ 3 đối tượng trở lên.', comparison_note = 'Khác ～と～と、どちらが～ですか (so sánh đúng 2 đối tượng, dùng どちら) — mẫu này dùng cho 3 đối tượng trở lên, hỏi bằng 何/だれ.', common_mistake = 'Dùng どちら thay vì 何/だれ khi hỏi trong phạm vi từ 3 đối tượng trở lên — phải hỏi "何が一番~ですか", không phải "どちらが~".' where id = 'c0c4818f-0258-5897-aadc-f102688da4b2';
update grammar_points set extra_examples_jp = ARRAY['今日は昨日ほど暑くないです。','弟は兄ほど背が高くないです。']::text[], extra_examples_vi = ARRAY['Hôm nay không nóng bằng hôm qua.','Em trai không cao bằng anh trai.']::text[], memory_tip = 'N2ほど~ない = N1 không bằng N2 — N2 (mốc so sánh) luôn đứng TRƯỚC ほど.', comparison_note = 'Khác ～より~ (so sánh HƠN) — ～ほど~ない diễn tả chiều ngược lại, N1 THUA N2.', common_mistake = 'Dùng thể khẳng định sau ほど (sai) — ほど luôn phải đi kèm THỂ PHỦ ĐỊNH ở cuối câu.' where id = 'ee0cb88a-1cb1-57a6-ab2c-513f5e2d706d';
update grammar_points set extra_examples_jp = ARRAY['今日は昨日より涼しいです。','新幹線は飛行機より安いです。']::text[], extra_examples_vi = ARRAY['Hôm nay mát hơn hôm qua.','Tàu shinkansen rẻ hơn máy bay.']::text[], memory_tip = 'N1はN2より = N1 hơn N2 — より đứng ngay sau đối tượng bị so sánh (mốc thua kém).', comparison_note = 'Khác ～ほど~ない~ (N1 KHÔNG bằng N2) — より diễn tả N1 HƠN N2, ほど~ない diễn tả chiều ngược lại.', common_mistake = 'Dùng thể phủ định của tính từ sau より khi muốn nói "không hơn" (sai) — phải đổi sang tính từ TRÁI NGHĨA thay vì phủ định.' where id = 'b3f5eec8-1e15-5a7b-ad6d-bf5bdb62acc7';
update grammar_points set extra_examples_jp = ARRAY['田中さんは学生に日本語を教えます。','私は友達に本を貸しました。']::text[], extra_examples_vi = ARRAY['Anh Tanaka dạy tiếng Nhật cho học sinh.','Tôi đã cho bạn mượn sách.']::text[], memory_tip = 'Nghĩ に như mũi tên chỉ đích đến — đánh dấu người NHẬN của hành động cho/dạy/mượn.', comparison_note = 'Khi đối tác không phải là người mà là tổ chức (công ty, trường học), không dùng に mà dùng から.', common_mistake = 'Nhầm lẫn giữa に và から khi chỉ người cho trong câu もらいます — cả hai đều dùng được nhưng から nhấn mạnh nguồn gốc rõ hơn.' where id = 'a1b2c3d4-0000-4000-8000-000000000008';
update grammar_points set extra_examples_jp = ARRAY['荷物が重いですね。私が持ちましょうか。','一緒に晩ご飯を作りましょうか。']::text[], extra_examples_vi = ARRAY['Đồ nặng quá nhỉ. Để tôi xách giúp nhé?','Cùng nấu bữa tối nhé?']::text[], memory_tip = 'ましょうか = "...nhé?" — vừa đề nghị vừa hỏi ý kiến người nghe, khác ましょう (khẳng định rủ rê).', comparison_note = 'Khác Vませんか (mời người khác làm gì đó) — ましょうか thiên về việc người nói chủ động đề nghị giúp đỡ hoặc rủ cùng làm.', common_mistake = 'Nhầm ましょうか (đề nghị, có tính hỏi ý kiến) với ましょう (rủ rê dứt khoát hơn, không hỏi ý kiến).' where id = 'a9c7422b-28fc-5d9d-a5fa-2e21cbe64ba1';
update grammar_points set extra_examples_jp = ARRAY['ここに車を止めないでください。','授業中にスマホを使わないでください。']::text[], extra_examples_vi = ARRAY['Xin đừng đỗ xe ở đây.','Xin đừng dùng điện thoại trong giờ học.']::text[], memory_tip = 'ないでください = thể ない + でください, nghĩa đen "xin đừng ở trong trạng thái làm việc đó".', comparison_note = 'Khác Vてください (nhờ làm gì đó) — ないでください là dạng phủ định, yêu cầu người nghe KHÔNG làm.', common_mistake = 'Chia sai động từ — phải dùng thể ない (書かないでください), không phải thể ます phủ định (書きませんでください là sai).' where id = '40bdac0c-56b6-57e3-907e-7e3d616df997';
update grammar_points set extra_examples_jp = ARRAY['毎朝六時に起きないといけない。','明日までにレポートを出さないといけません。']::text[], extra_examples_vi = ARRAY['Mỗi sáng tôi phải dậy lúc 6 giờ.','Tôi phải nộp báo cáo trước ngày mai.']::text[], memory_tip = 'ないと + いけない, nghĩa đen "không làm thì không được" → suy ra phải làm.', comparison_note = 'Cùng nghĩa với なければなりません nhưng ないといけない mang sắc thái khẩu ngữ, thân mật hơn.', common_mistake = 'Quên đổi động từ về thể ない trước khi thêm といけない (đúng: 書かないといけない, sai: 書くないといけない).' where id = '291620a5-e4ec-5a16-a8f8-e7f1aa567179';
update grammar_points set extra_examples_jp = ARRAY['早く帰らなくちゃいけない。','薬を忘れずに飲まなくちゃいけない。']::text[], extra_examples_vi = ARRAY['Tôi phải về sớm.','Tôi phải nhớ uống thuốc.']::text[], memory_tip = 'なくちゃ là dạng rút gọn thân mật của なくては — nghe giống văn nói hàng ngày, tự nhiên hơn.', comparison_note = 'Trang trọng hơn thì dùng なければなりません hoặc なくてはいけません; なくちゃ chỉ dùng trong hội thoại thân mật.', common_mistake = 'Dùng なくちゃ trong văn viết trang trọng (báo cáo, email công việc) — nên đổi sang なければなりません cho phù hợp.' where id = '34d2167f-9374-5d34-a402-bdd913a1941c';
update grammar_points set extra_examples_jp = ARRAY['日曜日は仕事に行かなくてもいいです。','高い辞書を買わなくてもいいですよ、アプリで十分です。']::text[], extra_examples_vi = ARRAY['Chủ nhật tôi không cần đi làm cũng được.','Không cần mua từ điển đắt tiền cũng được, dùng app là đủ rồi.']::text[], memory_tip = 'なくても + いい, nghĩa đen "dù không làm cũng ổn" → không bắt buộc phải làm.', comparison_note = 'Trái nghĩa với なければなりません (bắt buộc phải làm) — なくてもいいです cho phép KHÔNG làm.', common_mistake = 'Nhầm なくてもいいです (không bắt buộc) với てはいけません (bị cấm, không được làm) — hai ý nghĩa hoàn toàn khác nhau.' where id = '2e2ea440-9b42-59d4-8dc7-4be409359ac3';
update grammar_points set extra_examples_jp = ARRAY['図書館では静かにしなければなりません。','外国で運転するなら、国際免許を持っていなければなりません。']::text[], extra_examples_vi = ARRAY['Ở thư viện phải giữ yên lặng.','Nếu lái xe ở nước ngoài thì phải có bằng lái quốc tế.']::text[], memory_tip = 'なければ (nếu không làm) + なりません (không xong/không được) → "nếu không làm thì không được" = phải làm.', comparison_note = 'Trang trọng hơn なくちゃいけない／ないといけない, thường dùng trong văn viết, quy định, luật lệ.', common_mistake = 'Chia sai phần なければ — phải là thể ない bỏ い rồi thêm ければ (食べなければ, không phải 食べないければ).' where id = 'be07cc26-e73e-57f9-815a-a7ad7ea5675b';
update grammar_points set extra_examples_jp = ARRAY['私は北海道へ行ったことがあります。','すしを食べたことがありますか。']::text[], extra_examples_vi = ARRAY['Tôi đã từng đi Hokkaido.','Bạn đã từng ăn sushi chưa?']::text[], memory_tip = 'たこと (chuyện đã làm) + がある (có tồn tại) → nhấn mạnh KINH NGHIỆM đã từng trải qua.', comparison_note = 'Khác động từ thể た đơn thuần — たことがある nhấn mạnh kinh nghiệm, không chỉ là một thời điểm quá khứ.', common_mistake = 'Dùng nhầm thể ますform thay vì thể た trước ことがある (đúng: 行ったことがある, sai: 行きますことがある).' where id = '24db2e94-d6ab-5c1e-8762-8c5c4e336a9a';
update grammar_points set extra_examples_jp = ARRAY['週末は掃除したり、洗濯したりします。','休みの日はテレビを見たり、寝たりします。']::text[], extra_examples_vi = ARRAY['Cuối tuần tôi dọn dẹp, giặt giũ các thứ.','Ngày nghỉ tôi xem tivi, ngủ nghỉ các thứ.']::text[], memory_tip = 'たり…たりする dùng để liệt kê vài hành động TIÊU BIỂU (không đầy đủ) trong một khoảng thời gian.', comparison_note = 'Khác や (liệt kê danh từ tiêu biểu) — たり dùng để liệt kê ĐỘNG TỪ/hành động tiêu biểu.', common_mistake = 'Quên thêm する ở cuối câu — mẫu câu bắt buộc phải kết bằng する/した dù chỉ liệt kê một hành động.' where id = '001dda56-7a1a-5e9c-99ea-6a092f478601';
update grammar_points set extra_examples_jp = ARRAY['忙しい時は電話に出ないことがあります。','彼は約束を守らないことがある。']::text[], extra_examples_vi = ARRAY['Lúc bận đôi khi tôi không nghe điện thoại.','Anh ấy đôi khi không giữ lời hứa.']::text[], memory_tip = 'ないことがある, nghĩa đen "có (khi) việc không làm" → thỉnh thoảng không làm việc đó.', comparison_note = 'Là dạng phủ định của ることがある (thỉnh thoảng CÓ làm).', common_mistake = 'Nhầm với ないことはない (không phải là không...) — hai cấu trúc nhìn giống nhưng nghĩa khác hẳn.' where id = '19fd0c7b-94de-550d-b13e-a34b6c61dee8';
update grammar_points set extra_examples_jp = ARRAY['週末は一人で映画を見ることがあります。','電車の中で寝ることがあります。']::text[], extra_examples_vi = ARRAY['Cuối tuần thỉnh thoảng tôi xem phim một mình.','Thỉnh thoảng tôi ngủ gật trên tàu điện.']::text[], memory_tip = 'ることがある, nghĩa đen "có việc làm (đôi khi)" → hành động không thường xuyên nhưng thỉnh thoảng xảy ra.', comparison_note = 'Khác ています (đang làm/thói quen đều đặn) — ることがある chỉ tần suất THẤP, không đều đặn.', common_mistake = 'Nhầm ることがある (thỉnh thoảng CÓ làm) với ないことがある (thỉnh thoảng KHÔNG làm) khi dịch nhanh.' where id = '5654b8db-adca-5d0d-bd8a-08eedcf0ca4e';
update grammar_points set extra_examples_jp = ARRAY['晩ご飯を食べたあとで、散歩します。','シャワーを浴びたあとで、宿題をします。']::text[], extra_examples_vi = ARRAY['Sau khi ăn tối, tôi đi dạo.','Sau khi tắm xong, tôi làm bài tập.']::text[], memory_tip = 'た (đã xong) + あとで (sau đó) — nhấn mạnh trình tự trước-sau rõ ràng.', comparison_note = 'So với てから, たあとで nhấn mạnh việc trước đã HOÀN TẤT rồi mới làm việc sau.', common_mistake = 'Dùng nhầm thể ます trước あとで (食べますあとで là sai), phải dùng thể た (食べたあとで).' where id = '0fb13e20-3af9-5269-9862-f7b6d0c99ade';
update grammar_points set extra_examples_jp = ARRAY['手を洗ってから、ご飯を食べます。','日本に来てから、三年になります。']::text[], extra_examples_vi = ARRAY['Rửa tay xong rồi mới ăn cơm.','Từ khi đến Nhật đã được 3 năm rồi.']::text[], memory_tip = 'てform + から (từ đó) — nhấn mạnh mốc bắt đầu, hành động sau nối liền hành động trước.', comparison_note = 'Khác たあとで — てから nhấn mạnh MỐC THỜI GIAN bắt đầu, dùng được với khoảng thời gian kéo dài (三年になる).', common_mistake = 'Nhầm てから (sau khi/từ khi) với まえに (trước khi) — trình tự thời gian ngược nhau hoàn toàn.' where id = '17d5e613-034f-5c28-b921-6cac9a82b059';
update grammar_points set extra_examples_jp = ARRAY['日本へ行くとき、パスポートを忘れないでください。','疲れたとき、甘いものを食べます。']::text[], extra_examples_vi = ARRAY['Khi đi Nhật, đừng quên hộ chiếu.','Khi mệt, tôi ăn đồ ngọt.']::text[], memory_tip = 'Động từ る trước とき = việc chưa xảy ra; động từ た trước とき = việc đã xảy ra rồi mới đến sự việc kia.', comparison_note = 'Khác ながら (làm 2 việc CÙNG LÚC) — とき chỉ mốc thời điểm xảy ra sự việc khác, không nhất thiết đồng thời.', common_mistake = 'Nhầm 行くとき (lúc chuẩn bị đi, chưa tới nơi) với 行ったとき (sau khi đã đến nơi) — thể động từ trước とき đổi hẳn nghĩa câu.' where id = '2eab616d-84b1-59fa-962c-6e70cbb69fe7';
update grammar_points set extra_examples_jp = ARRAY['寝るまえに、歯を磨きます。','旅行のまえに、荷物を準備します。']::text[], extra_examples_vi = ARRAY['Trước khi ngủ, tôi đánh răng.','Trước khi đi du lịch, tôi chuẩn bị hành lý.']::text[], memory_tip = 'まえに luôn đi với động từ thể nguyên dạng (る), dù cả câu ở quá khứ hay tương lai.', comparison_note = 'Ngược nghĩa với あとで／てから (sau khi) — まえに luôn dùng động từ thể từ điển bất kể thì của câu.', common_mistake = 'Dùng nhầm thể た trước まえに (食べたまえに là sai), phải là 食べるまえに dù cả câu ở quá khứ.' where id = '92d9ba87-b8cb-5da4-baa9-e008061235bf';
update grammar_points set extra_examples_jp = ARRAY['料理を作るのが上手です。','早起きするのが苦手です。']::text[], extra_examples_vi = ARRAY['Tôi nấu ăn giỏi.','Tôi không giỏi dậy sớm.']::text[], memory_tip = 'の biến động từ thành cụm danh từ, rồi が đánh dấu chủ thể cho tính từ như すき／じょうず／へた.', comparison_note = 'Khác のは (nêu chủ đề chung) — のが gắn liền với tính từ chỉ SỞ THÍCH/NĂNG LỰC cụ thể.', common_mistake = 'Quên bắt buộc phải dùng が sau の trước các tính từ này, không được thay bằng を hay は tùy tiện.' where id = '3d3b2bfd-7c35-59a5-b69b-6726924b3cf5';
update grammar_points set extra_examples_jp = ARRAY['私が一番好きなのはラーメンです。','毎朝運動するのは体にいいです。']::text[], extra_examples_vi = ARRAY['Món tôi thích nhất là mì ramen.','Tập thể dục mỗi sáng thì tốt cho sức khỏe.']::text[], memory_tip = 'のは biến cả một mệnh đề thành chủ đề của câu, giống "việc mà... thì...".', comparison_note = 'Khác のが — のは nêu CHỦ ĐỀ để bàn luận, còn のが gắn với tính từ chỉ khả năng/sở thích cụ thể.', common_mistake = 'Thêm thừa に sau phần bổ ngữ danh từ cuối câu (8月にです là sai, đúng là 8月です).' where id = '6b7c7e2c-f0b3-525a-9d31-9fded6659116';
update grammar_points set extra_examples_jp = ARRAY['電気を消すのを忘れないでください。','彼が引っ越したのを知っていますか。']::text[], extra_examples_vi = ARRAY['Đừng quên tắt đèn.','Bạn có biết anh ấy đã chuyển nhà không?']::text[], memory_tip = 'のを biến động từ thành danh từ để làm TÂN NGỮ cho các động từ như 忘れる／知る／やめる.', comparison_note = 'Khác のが／のは về vai trò ngữ pháp — のを luôn đóng vai trò tân ngữ, không phải chủ ngữ hay chủ đề.', common_mistake = 'Nhầm lẫn giữa の và こと khi danh từ hóa — cả hai đều dùng được nhưng こと trang trọng hơn, ít dùng trực tiếp với 忘れる/見る.' where id = 'f777f0b8-312f-5912-9b97-e95bfdb1a811';
update grammar_points set extra_examples_jp = ARRAY['この映画はとても面白いと思います。','彼はもうすぐ来ると思います。']::text[], extra_examples_vi = ARRAY['Tôi nghĩ bộ phim này rất hay.','Tôi nghĩ anh ấy sắp đến rồi.']::text[], memory_tip = 'と đánh dấu nội dung suy nghĩ, giống như đóng khung ý nghĩ trong đầu, rồi 思います kết câu.', comparison_note = 'Khác と言います (lời NÓI RA thành tiếng) — と思います chỉ dùng cho suy nghĩ, ý kiến cá nhân.', common_mistake = 'Khi hỏi ý kiến, thừa と sau どう — phải nói ～についてどう思いますか, không phải どうと思いますか.' where id = '738d780d-cb0c-5da4-86b6-32bf35566022';
update grammar_points set extra_examples_jp = ARRAY['先生は「明日テストがあります」と言いました。','母は忙しいと言っていました。']::text[], extra_examples_vi = ARRAY['Thầy giáo nói rằng ngày mai có bài kiểm tra.','Mẹ tôi nói là mẹ bận.']::text[], memory_tip = 'と言います dùng để trích dẫn lời nói: câu trực tiếp cho vào 「」, câu gián tiếp dùng thể thông thường trước と.', comparison_note = 'Khác と思います (suy nghĩ trong đầu, chưa chắc nói ra) — と言います là lời đã được NÓI RA thành tiếng.', common_mistake = 'Nghĩ thời của phần trích dẫn phải đổi theo thời câu chính — thực ra thời trong 「」độc lập, không đổi theo.' where id = '06ff9c8c-127c-5157-9b8c-03c887303336';
update grammar_points set extra_examples_jp = ARRAY['練習して、日本語が上手になりました。','秋になると、涼しくなります。']::text[], extra_examples_vi = ARRAY['Nhờ luyện tập, tiếng Nhật của tôi đã giỏi lên.','Khi vào thu, trời trở nên mát mẻ.']::text[], memory_tip = 'Tính từ đuôi い đổi い→く rồi + なる; tính từ đuôi な hoặc danh từ thì thêm に + なる — cả hai đều diễn tả sự BIẾN ĐỔI.', comparison_note = 'Khác する (chủ động làm cho thay đổi, có tác nhân) — なる diễn tả sự thay đổi TỰ NHIÊN, không chủ ý.', common_mistake = 'Quên đổi tính từ đuôi い thành く trước なる (viết sai 忙しいになる thay vì 忙しくなる).' where id = 'a8cd75af-775d-5276-b093-d93200a4709c';
update grammar_points set extra_examples_jp = ARRAY['このケーキ、おいしいでしょう?','明日は休みでしょう?']::text[], extra_examples_vi = ARRAY['Bánh này ngon đúng không?','Ngày mai nghỉ đúng không?']::text[], memory_tip = 'でしょう lên giọng ở cuối câu = xác nhận, giống "đúng không nào?" trong tiếng Việt.', comparison_note = 'Khác 多分～でしょう (dự đoán, không mong đợi xác nhận) — でしょう? lên giọng để HỎI XÁC NHẬN người nghe đồng ý.', common_mistake = 'Nhầm ngữ điệu — cùng でしょう nhưng xuống giọng mang nghĩa "có lẽ", lên giọng mới mang nghĩa "đúng không?".' where id = '45fa9d08-7db9-5a8b-adde-219509b28c13';
update grammar_points set extra_examples_jp = ARRAY['明日は多分雨が降るでしょう。','彼は多分もう寝ているでしょう。']::text[], extra_examples_vi = ARRAY['Ngày mai có lẽ sẽ mưa.','Chắc là anh ấy đang ngủ rồi.']::text[], memory_tip = '多分 (có lẽ) đứng đầu câu báo trước, でしょう xuống giọng ở cuối để xác nhận mức độ suy đoán cao (trên 90%).', comparison_note = 'Khác と思います (ý kiến chủ quan, không nhất thiết chắc chắn) — 多分～でしょう nhấn mạnh mức độ tin chắc cao dựa trên căn cứ.', common_mistake = 'Lên giọng cuối câu khi nói でしょう trong ngữ cảnh này sẽ biến thành câu hỏi xác nhận, làm sai nghĩa dự đoán ban đầu.' where id = 'a42d66a4-9dc8-5cc9-8322-13ce5d4802ca';
update grammar_points set extra_examples_jp = ARRAY['お金がないから、旅行に行けません。','眠いから、早く寝ます。']::text[], extra_examples_vi = ARRAY['Vì không có tiền nên tôi không thể đi du lịch.','Vì buồn ngủ nên tôi đi ngủ sớm.']::text[], memory_tip = 'から đứng sau lý do, giống "vì...nên" nhưng vế lý do đứng TRƯỚC trong câu tiếng Nhật.', comparison_note = 'Khác ので (lý do khách quan, lịch sự, mềm mỏng hơn) — から mang tính chủ quan, dùng được với mệnh lệnh/rủ rê ở vế sau.', common_mistake = 'Dùng から trong tình huống xin phép trang trọng thay vì ので — nghe hơi cộc, thiếu tế nhị.' where id = '414df9f6-606f-5584-a2ef-3b72b999f769';
update grammar_points set extra_examples_jp = ARRAY['すみませんが、写真を撮ってもらえますか。','この店は安いですが、あまりおいしくないです。']::text[], extra_examples_vi = ARRAY['Xin lỗi, bạn có thể chụp ảnh giúp tôi không?','Quán này rẻ nhưng không ngon lắm.']::text[], memory_tip = 'が nối 2 câu tương phản, giống "nhưng" — nhưng cũng dùng để mở đầu câu lịch sự như すみませんが.', comparison_note = 'Khác けど (văn nói thân mật hơn) — が trung tính, dùng được cả văn nói lẫn văn viết lịch sự.', common_mistake = 'Hiểu が luôn mang nghĩa "nhưng" — thực ra trong すみませんが／しつれいですが, が chỉ nối câu nhẹ nhàng, không mang ý tương phản.' where id = '5164d278-2cee-5fac-ad5a-1db92164fac5';
update grammar_points set extra_examples_jp = ARRAY['頭が痛いので、今日は休みます。','時間がないので、急ぎましょう。']::text[], extra_examples_vi = ARRAY['Vì đau đầu nên hôm nay tôi nghỉ.','Vì không có thời gian nên chúng ta nhanh lên nhé.']::text[], memory_tip = 'ので nghe nhẹ nhàng, lịch sự hơn から — thường dùng khi xin phép hoặc giải thích khách quan.', comparison_note = 'Khác から (lý do chủ quan, dùng được với mệnh lệnh/rủ rê) — ので mang tính khách quan, tránh dùng với mệnh lệnh mạnh.', common_mistake = 'Quên thêm な trước ので khi vế trước là danh từ hoặc tính từ な (đúng: 静かなので, sai: 静かだので).' where id = '1b552490-7571-516b-b2dc-36a7dbc7860e';
update grammar_points set extra_examples_jp = ARRAY['田中さんは結婚しています。','毎朝ジョギングをしています。']::text[], extra_examples_vi = ARRAY['Anh Tanaka đã kết hôn rồi.','Mỗi sáng tôi chạy bộ.']::text[], memory_tip = 'ている có 3 nghĩa chính: đang làm, trạng thái còn lại, hoặc thói quen/nghề nghiệp — dựa vào ngữ cảnh để phân biệt.', comparison_note = 'Khác ました (hành động đã xong, một lần) — ている có thể chỉ trạng thái kéo dài liên tục đến hiện tại.', common_mistake = 'Dịch 結婚しています thành "đang kết hôn" (đang làm lễ cưới) — nghĩa đúng là "đã kết hôn, hiện đang ở trạng thái đã lập gia đình".' where id = '765675e4-cfb0-5f75-b558-378d7d4187e4';
update grammar_points set extra_examples_jp = ARRAY['宿題はまだ終わっていません。','彼にはまだ連絡していません。']::text[], extra_examples_vi = ARRAY['Bài tập vẫn chưa xong.','Tôi vẫn chưa liên lạc với anh ấy.']::text[], memory_tip = 'まだ (vẫn) + ていません (chưa ở trạng thái đã xong) — nhấn mạnh việc chưa hoàn thành nhưng có ý định làm.', comparison_note = 'Khác もう～ました (đã làm xong rồi) — まだ～ていません là câu trả lời phủ định tự nhiên cho câu hỏi もう～ましたか.', common_mistake = 'Trả lời もう食べましたか bằng いいえ、食べません (sai, nghe như "sẽ không làm") thay vì まだ食べていません.' where id = '3f9e2a82-420e-530a-af81-b63670dd8bf2';
update grammar_points set extra_examples_jp = ARRAY['もう晩ご飯を食べましたか。はい、もう食べました。','チケットはもう買いましたか。']::text[], extra_examples_vi = ARRAY['Bạn ăn tối chưa? Vâng, tôi ăn rồi.','Bạn đã mua vé chưa?']::text[], memory_tip = 'もう (đã) đứng trước động từ thể ました để hỏi/khẳng định việc đã hoàn thành.', comparison_note = 'Câu trả lời phủ định của もう～ましたか không phải là もう～ませんでした mà là まだ～ていません.', common_mistake = 'Trả lời phủ định bằng もうしませんでした (sai) thay vì まだしていません (đúng).' where id = '11e55bb3-1e8a-525b-bea7-f0c25d43e8b0';
update grammar_points set extra_examples_jp = ARRAY['今日はコーヒーを一杯だけ飲みました。','教室には学生が二人だけいます。']::text[], extra_examples_vi = ARRAY['Hôm nay tôi chỉ uống một ly cà phê thôi.','Trong lớp chỉ có 2 học sinh thôi.']::text[], memory_tip = 'だけ = "chỉ, chỉ có" — luôn đứng ngay sau từ mà nó giới hạn.', comparison_note = 'Khác しか～ない (cũng nghĩa "chỉ" nhưng bắt buộc đi với động từ phủ định) — だけ dùng được cả câu khẳng định.', common_mistake = 'Dùng だけ chung với động từ phủ định giống しか (viết 少ししか食べだけません là sai) — だけ không cần đi kèm phủ định.' where id = '864c47fe-5009-5183-b55d-619ea5418d32';
update grammar_points set extra_examples_jp = ARRAY['バスがなかなか来ません。','漢字がなかなか覚えられません。']::text[], extra_examples_vi = ARRAY['Xe buýt mãi mà không đến.','Chữ Hán mãi mà tôi không nhớ được.']::text[], memory_tip = 'なかなか đứng trước động từ phủ định để nhấn mạnh "mất nhiều công sức/thời gian mà vẫn chưa được".', comparison_note = 'Khác 全然～ない (hoàn toàn không, phủ định tuyệt đối) — なかなか～ない nhấn mạnh sự khó khăn, trì hoãn.', common_mistake = 'Nhầm なかなか ở câu khẳng định (なかなか上手です = khá giỏi đấy) với nghĩa "mãi mà không" ở câu phủ định — hai cách dùng khác hẳn.' where id = '49b30190-ff03-516b-8799-bb35cd777263';
update grammar_points set extra_examples_jp = ARRAY['どんなに頑張っても、うまくいきません。','いくら呼んでも、返事がありません。']::text[], extra_examples_vi = ARRAY['Dù cố gắng thế nào cũng không suôn sẻ.','Dù gọi bao nhiêu lần cũng không có ai trả lời.']::text[], memory_tip = 'ても (dù...) + ない (vẫn không) — kết quả trái với mong đợi thông thường.', comparison_note = 'Khác から／ので (quan hệ nhân-quả thuận) — ても diễn tả quan hệ ngược, kết quả không như dự đoán.', common_mistake = 'Quên đổi động từ về thể て trước khi thêm も (đúng: 買っても, sai: 買うも).' where id = '6fbb8fd5-792a-5eed-beb3-bc281734802a';
update grammar_points set extra_examples_jp = ARRAY['昨日は全然寝ませんでした。','この問題は全然分かりません。']::text[], extra_examples_vi = ARRAY['Hôm qua tôi hoàn toàn không ngủ được chút nào.','Vấn đề này tôi hoàn toàn không hiểu gì cả.']::text[], memory_tip = '全然 trong ngữ pháp chuẩn luôn đi cùng phủ định — nhớ "全然...không" giống "chẳng...tí nào".', comparison_note = 'Khác なかなか～ない (khó khăn, mất công mới được) — 全然～ない là phủ định tuyệt đối, gần như 0%.', common_mistake = 'Trong văn nói hiện đại nhiều người dùng 全然 với nghĩa khẳng định (全然大丈夫 = hoàn toàn ổn) — đây là cách dùng thân mật, khác ngữ pháp gốc.' where id = '4cb16502-c36e-56e0-910c-23417cc615fc';
update grammar_points set extra_examples_jp = ARRAY['冷蔵庫の中に卵や牛乳などがあります。','休みの日は掃除や洗濯などをします。']::text[], extra_examples_vi = ARRAY['Trong tủ lạnh có trứng, sữa và những thứ khác.','Ngày nghỉ tôi làm những việc như dọn dẹp, giặt giũ.']::text[], memory_tip = 'や liệt kê vài ví dụ TIÊU BIỂU (không đầy đủ), khác と liệt kê ĐẦY ĐỦ tất cả.', comparison_note = 'Khác と (liệt kê chính xác, đầy đủ hết các đối tượng) — や chỉ nêu vài cái tiêu biểu, còn nhiều thứ khác chưa kể hết.', common_mistake = 'Dùng や nhưng hiểu nhầm là liệt kê đầy đủ giống と — や luôn ngầm ý "và những thứ khác", nhất là khi có など đi kèm.' where id = '449e4ae7-8b67-52b2-812b-420505001a4f';
update grammar_points set extra_examples_jp = ARRAY['母が私に誕生日プレゼントをくれました。','私は先生に辞書をもらいました。']::text[], extra_examples_vi = ARRAY['Mẹ đã tặng tôi quà sinh nhật.','Tôi đã nhận được cuốn từ điển từ thầy giáo.']::text[], memory_tip = 'あげる = cho đi (hướng ra ngoài), もらう = nhận về (hướng vào từ người khác), くれる = người khác cho TÔI (luôn hướng về phía người nói).', comparison_note = 'Khác ～てあげます／～てもらいます／～てくれます (thêm động từ thể て để diễn tả HÀNH ĐỘNG giúp đỡ, không chỉ đồ vật).', common_mistake = 'Dùng あげます khi người khác tặng cho mình — phải dùng くれます, vì あげます chỉ dùng khi chủ ngữ là người cho.' where id = 'b2c3d4e5-0000-4000-8000-000000000201';
update grammar_points set extra_examples_jp = ARRAY['妹の宿題を手伝ってあげました。','友達に道を教えてもらいました。']::text[], extra_examples_vi = ARRAY['Tôi đã giúp em gái làm bài tập.','Tôi đã được bạn chỉ đường giúp.']::text[], memory_tip = 'てあげます = TÔI làm giúp người khác; てもらいます = TÔI được người khác làm giúp cho mình (người làm đánh dấu bằng に).', comparison_note = 'Khác あげます／もらいます (chỉ cho/nhận đồ vật) — thêm động từ thể て để diễn tả cho/nhận một HÀNH ĐỘNG giúp đỡ.', common_mistake = 'Dùng てあげます với người trên (thầy cô, cấp trên) nghe như đang kể ơn, thiếu lịch sự — nên tránh dùng trực tiếp.' where id = 'b2c3d4e5-0000-4000-8000-000000000202';
update grammar_points set extra_examples_jp = ARRAY['姉が宿題を手伝ってくれました。','先生が難しい漢字を説明してくれました。']::text[], extra_examples_vi = ARRAY['Chị gái đã giúp tôi làm bài tập.','Thầy giáo đã giải thích giúp tôi chữ Hán khó.']::text[], memory_tip = 'てくれます luôn hướng về phía TÔI (hoặc người trong nhóm của tôi) — người khác chủ động làm giúp, mang sắc thái biết ơn.', comparison_note = 'Khác てもらいます (TÔI là chủ ngữ, chủ động nhờ/nhận được giúp đỡ) — てくれます thì NGƯỜI KHÁC là chủ ngữ, chủ động giúp tôi.', common_mistake = 'Nhầm chủ ngữ giữa てくれます và てもらいます — cùng tình huống nhưng đổi chủ ngữ thì trợ từ đánh dấu người kia cũng đổi theo.' where id = 'b2c3d4e5-0000-4000-8000-000000000203';
update grammar_points set extra_examples_jp = ARRAY['もし宝くじが当たったら、世界旅行をしたいです。','もし明日雨が降ったら、試合は中止です。']::text[], extra_examples_vi = ARRAY['Nếu trúng số thì tôi muốn đi du lịch vòng quanh thế giới.','Nếu ngày mai trời mưa thì trận đấu sẽ bị hủy.']::text[], memory_tip = 'もし đứng đầu câu báo hiệu "giả sử nếu như...", giúp câu điều kiện với たら rõ nghĩa giả định hơn.', comparison_note = 'もし chỉ là trạng từ nhấn mạnh đi kèm たら — không bắt buộc phải có, nhưng thêm vào giúp câu rõ tính giả định hơn.', common_mistake = 'Dùng もし nhưng quên vế sau phải kết bằng たら (không phải と hay ば) trong mẫu câu này.' where id = 'b2c3d4e5-0000-4000-8000-000000000205';
update grammar_points set extra_examples_jp = ARRAY['この薬を飲んだら、すぐ元気になりますよ。','20歳になったら、お酒が飲めます。']::text[], extra_examples_vi = ARRAY['Uống thuốc này vào là sẽ khỏe ngay thôi.','Khi đủ 20 tuổi thì được uống rượu.']::text[], memory_tip = 'Chia động từ về thể た rồi thêm ら — たら dùng được cho cả điều kiện giả định lẫn trình tự thời gian chắc chắn xảy ra.', comparison_note = 'Khác と (điều kiện tất yếu, không dùng được với mệnh lệnh/rủ rê ở vế sau) — たら linh hoạt hơn, dùng được cả với câu mệnh lệnh, đề nghị.', common_mistake = 'Nhầm たら (điều kiện) với た (chỉ đơn thuần quá khứ) — phải thêm ら mới mang nghĩa "nếu/khi".' where id = 'b2c3d4e5-0000-4000-8000-000000000204';
update grammar_points set extra_examples_jp = ARRAY['「顔が赤いですね。」「熱があるんです。」','電車が止まっているんです。事故があったらしいです。']::text[], extra_examples_vi = ARRAY['Mặt anh đỏ nhỉ. Vì tôi đang bị sốt đấy.','Tàu điện đang dừng đó. Nghe nói là có tai nạn.']::text[], memory_tip = 'Nghĩ んです như thêm lời giải thích ''là vì...'' phía sau câu, không phải chỉ kể một sự thật suông.', comparison_note = 'Khác câu thường (V/Adj/Nです) chỉ nêu sự thật khách quan, んです luôn thêm sắc thái giải thích, xác nhận bối cảnh.', common_mistake = 'Quên đổi danh từ và tính từ đuôい な sang thể thông thường trước んです — không nói 病気んです mà phải là 病気なんです.' where id = '91900726-0a09-58b2-93ba-820d7b479174';
update grammar_points set extra_examples_jp = ARRAY['漢字が覚えられないんですが、どう勉強したらいいですか。','空港へは何で行ったらいいですか。']::text[], extra_examples_vi = ARRAY['Tôi không nhớ được chữ Hán, vậy nên học thế nào thì tốt ạ?','Nên đi bằng gì để đến sân bay thì tốt ạ?']::text[], memory_tip = 'Nhớ mẫu [từ hỏi] + Vたら + いいですか = ''nên... thế nào/gì thì được?'' — luôn dùng để xin lời khuyên.', comparison_note = 'So với Vたほうがいいです (lời khuyên chủ động của người nói), mẫu này là câu hỏi xin lời khuyên từ phía người nghe.', common_mistake = 'Quên giữ thể た (quá khứ) của động từ trước たら dù câu mang nghĩa tương lai — vẫn phải chia theo thể た.' where id = '99a262c4-fe93-561d-87f7-301b5e9beefd';
update grammar_points set extra_examples_jp = ARRAY['お忙しいところすみませんが、この書類にサインしていただけませんか。','もう一度説明していただけませんか。']::text[], extra_examples_vi = ARRAY['Xin lỗi vì đang làm phiền lúc anh bận, anh có thể ký vào tài liệu này giúp tôi được không?','Anh có thể giải thích lại một lần nữa giúp tôi được không?']::text[], memory_tip = 'いただけませんか lịch sự hơn てくれませんか vì dùng khiêm nhường ngữ いただく (nhận) kết hợp phủ định nghi vấn.', comparison_note = 'Lịch sự hơn hẳn Vてくれませんか và Vてください, thường dùng khi nhờ người trên, khách hàng hoặc người không thân quen.', common_mistake = 'Nhầm いただけませんか (xin phép được NHẬN việc đó) với くださいませんか (xin đối phương LÀM cho) tuy nghĩa gần giống nhưng chủ thể hành động ẩn khác nhau.' where id = '1682c5a5-7663-58db-9eeb-f1b452e09a42';
update grammar_points set extra_examples_jp = ARRAY['「今日は元気がないですね。」「実は、昨日あまり寝ていないんです。」','会議に出られないんです。急な用事ができてしまいました。']::text[], extra_examples_vi = ARRAY['Hôm nay anh trông không được khỏe nhỉ. Thật ra là hôm qua tôi ngủ không đủ giấc.','Tôi không tham dự cuộc họp được. Vì có việc gấp phát sinh.']::text[], memory_tip = 'んです ở đây đóng vai trò như ''là vì...'' — luôn xuất hiện khi cần giải thích nguyên nhân cho điều vừa nói.', comparison_note = 'Khác から/ので chỉ nối một câu nguyên nhân-kết quả đơn thuần, ~んです nhấn mạnh việc GIẢI THÍCH bối cảnh cho người nghe hiểu.', common_mistake = 'Dùng んです để kể một sự thật khách quan không cần giải thích gì sẽ khiến câu nghe thừa hoặc sai ngữ cảnh giao tiếp.' where id = '2ed48bed-5f1b-57dc-a72f-afe69d09ae84';
update grammar_points set extra_examples_jp = ARRAY['「ずいぶん荷物が多いですね。」「引っ越すんですか。」','どうしてそんなに日本語が上手なんですか。']::text[], extra_examples_vi = ARRAY['Sao hành lý nhiều thế nhỉ. Anh chuyển nhà à?','Sao anh giỏi tiếng Nhật đến thế vậy?']::text[], memory_tip = 'Thấy điều gì lạ thì hỏi bằng んですか, giống kiểu ''chuyện gì đang xảy ra vậy?''', comparison_note = 'So với ~ますか (câu hỏi thông thường), ~んですか luôn hàm ý người hỏi đã quan sát hoặc nghe thấy điều gì đó trước khi hỏi.', common_mistake = 'Dùng んですか để hỏi thông tin đơn thuần, không có ngữ cảnh quan sát trước, sẽ khiến câu hỏi nghe tò mò quá mức.' where id = 'b0a4841d-49e3-59e9-bce6-caaf958587b5';
update grammar_points set extra_examples_jp = ARRAY['明日の映画のチケットがあるんですが、一緒に行きませんか。','ちょっとお願いがあるんですが、今よろしいですか。']::text[], extra_examples_vi = ARRAY['Tôi có vé xem phim ngày mai, anh có muốn đi cùng không?','Tôi có việc muốn nhờ một chút, bây giờ anh có tiện không?']::text[], memory_tip = 'んですが như lời ''rào trước'' — nêu hoàn cảnh rồi mới nhờ vả hoặc mời gọi để câu nghe nhẹ nhàng, không đường đột.', comparison_note = 'Khác けど/が chỉ đơn thuần nối hai câu tương phản, んですが mang thêm sắc thái giải thích bối cảnh trước khi vào yêu cầu chính.', common_mistake = 'Bỏ hẳn phần sau んですが dù người nghe chưa hiểu ý gì — chỉ nên lược bỏ khi nội dung đã đủ rõ ràng, tránh lạm dụng.' where id = '962a986f-a4dd-5bfa-8ea5-334bc2ab5a86';
update grammar_points set extra_examples_jp = ARRAY['このレストランではクレジットカードが使えます。','図書館で無料のWi-Fiが利用できます。']::text[], extra_examples_vi = ARRAY['Ở nhà hàng này có thể dùng được thẻ tín dụng.','Ở thư viện có thể sử dụng được Wi-Fi miễn phí.']::text[], memory_tip = 'Khi động từ chuyển sang thể khả năng, trợ từ を biến thành が — nhớ ''thể khả năng luôn đi với が''.', comparison_note = 'So với động từ khả năng đơn thuần, mẫu này nhấn mạnh cấu trúc trợ từ が thay cho を trong câu có tân ngữ.', common_mistake = 'Quên đổi を thành が sau khi chia động từ sang thể khả năng — viết ドルを替えられます nghe không tự nhiên bằng ドルが替えられます.' where id = 'b3cb3ebc-086d-5336-86d6-a444c30724a5';
update grammar_points set extra_examples_jp = ARRAY['財布の中に千円しかありません。','このクラスには学生が5人しかいません。']::text[], extra_examples_vi = ARRAY['Trong ví chỉ có đúng một nghìn yên thôi.','Lớp này chỉ có vỏn vẹn 5 học sinh thôi.']::text[], memory_tip = 'しか luôn đi kèm phủ định — nhớ ''しか + không'' nghĩa là ''chỉ có bấy nhiêu, không hơn''.', comparison_note = 'Khác だけ (đi với thể khẳng định, trung tính), しか + phủ định mang sắc thái nhấn mạnh sự ít ỏi, đôi khi có ý tiếc nuối.', common_mistake = 'Chia động từ ở thể khẳng định sau しか là sai ngữ pháp — しか bắt buộc phải đi kèm động từ hoặc tính từ ở thể phủ định.' where id = '6da97135-c013-5546-9c59-16df67480a94';
update grammar_points set extra_examples_jp = ARRAY['漢字は難しいですが、ひらがなは簡単です。','肉は食べますが、魚は食べません。']::text[], extra_examples_vi = ARRAY['Chữ Hán thì khó, nhưng chữ Hiragana thì lại dễ.','Thịt thì tôi có ăn, nhưng cá thì tôi không ăn.']::text[], memory_tip = 'Hai は trong một câu = so sánh hai điều trái ngược nhau, giống kiểu ''còn về... thì...'' trong tiếng Việt.', comparison_note = 'Khác は chỉ dùng để nêu chủ đề đơn thuần (một は trong câu), ở đây hai は xuất hiện cùng lúc để tạo phép so sánh tương phản.', common_mistake = 'Giữ nguyên を/が ở cả hai vế thay vì đổi thành は khi muốn nhấn mạnh sự đối lập giữa hai điều.' where id = 'dd3b2439-3ab7-5944-a4f3-a7bdda1bb1df';
update grammar_points set extra_examples_jp = ARRAY['田中さんは英語が話せます。中国語も話せます。','昨日はパンを食べました。今日もパンを食べます。']::text[], extra_examples_vi = ARRAY['Anh Tanaka nói được tiếng Anh. Anh ấy cũng nói được cả tiếng Trung.','Hôm qua tôi đã ăn bánh mì. Hôm nay tôi cũng ăn bánh mì.']::text[], memory_tip = 'も nghĩa là ''cũng'', thay thế cho を/が, còn với trợ từ khác thì も được thêm vào sau (には、とも...).', comparison_note = 'Trái ngược với ~は~ (so sánh, tương phản), ~も~ dùng khi hai vế CÙNG tính chất, cùng đúng như nhau.', common_mistake = 'Giữ nguyên を/が rồi thêm も vào phía sau (ví dụ 本をも読みます) là sai — phải bỏ を/が rồi mới thêm も.' where id = '437e1a49-29af-580a-becd-0fd69b4414e0';
update grammar_points set extra_examples_jp = ARRAY['弟はギターが弾けます。','私は朝早く起きられません。']::text[], extra_examples_vi = ARRAY['Em trai tôi chơi được đàn ghi-ta.','Tôi không dậy sớm được vào buổi sáng.']::text[], memory_tip = 'Nhóm 1 chuyển âm cuối hàng い sang hàng え rồi thêm る; nhóm 2 chỉ cần bỏ ます thêm られる vào thân từ.', comparison_note = 'Khác thể ý định (意向形) chỉ diễn tả mong muốn hoặc dự định làm, thể khả năng diễn tả NĂNG LỰC làm được hay không.', common_mistake = 'Nhầm cách chia giữa nhóm 1 và nhóm 2 — ví dụ 食べる (nhóm 2) phải chia thành 食べられる chứ không phải theo kiểu nhóm 1.' where id = 'daa1b484-fe1a-5ed6-afbb-302d647b4078';
update grammar_points set extra_examples_jp = ARRAY['来月、この町に新しい病院ができます。','3年前、駅の前に大きい公園ができました。']::text[], extra_examples_vi = ARRAY['Tháng sau, ở thị trấn này sẽ có một bệnh viện mới được xây xong.','3 năm trước, phía trước ga có một công viên lớn được xây xong.']::text[], memory_tip = 'できます ở nghĩa này khác nghĩa ''có thể làm'' — nhớ theo ngữ cảnh: địa điểm (に) + công trình (が) = ''mọc lên, xây xong''.', comparison_note = 'Cùng từ できます nhưng khác nghĩa với できます chỉ khả năng (bài 27) — cần phân biệt qua chủ ngữ và trợ từ đi kèm (に...が).', common_mistake = 'Nhầm lẫn hai nghĩa của できます: ''có thể làm được'' và ''được xây/hoàn thành xong'' — cần dựa vào chủ ngữ là người hay công trình để phân biệt.' where id = 'da9be1ff-acb8-5c02-9934-da164713750f';
update grammar_points set extra_examples_jp = ARRAY['隣の部屋から赤ちゃんの泣き声が聞こえます。','夜、星がたくさん見えます。']::text[], extra_examples_vi = ARRAY['Từ phòng bên cạnh nghe thấy tiếng em bé khóc.','Vào ban đêm, có thể nhìn thấy rất nhiều ngôi sao.']::text[], memory_tip = 'みえる/きこえる = tự nhiên lọt vào mắt/tai, không cần cố ý nhìn hoặc nghe, khác hẳn 見られる/聞ける.', comparison_note = 'Khác động từ khả năng thông thường (見られる、聞ける) cần chủ ý và điều kiện, みえる/きこえる chỉ đơn thuần là hiện tượng tự nhiên.', common_mistake = 'Dùng を thay vì が sau danh từ trước みえます/きこえます — hai động từ này luôn đi với が, không phải を.' where id = 'fb8f6d11-b1fd-505b-a3d4-dba0ba98b7f9';
update grammar_points set extra_examples_jp = ARRAY['このアパートは駅から近いし、家賃も安いし、とても気に入っています。','今日は雨も降っているし、風も強いし、出かけたくないです。']::text[], extra_examples_vi = ARRAY['Căn hộ này vừa gần ga, vừa tiền thuê rẻ, nên tôi rất thích.','Hôm nay vừa có mưa, vừa gió mạnh, nên tôi không muốn ra ngoài.']::text[], memory_tip = 'し giống dấu ''vừa... vừa...'' khi liệt kê, ngụ ý còn nhiều lý do khác chưa kể hết.', comparison_note = 'Khác から chỉ nêu MỘT nguyên nhân duy nhất và dứt khoát, し dùng để liệt kê NHIỀU lý do hoặc đặc điểm cùng chiều.', common_mistake = 'Chỉ dùng một し duy nhất trong câu — thường phải lặp lại し ít nhất hai lần khi liệt kê để đúng văn phong tự nhiên.' where id = 'c75cd551-ca8e-512b-a8e3-73eaf172ee4f';
update grammar_points set extra_examples_jp = ARRAY['スマホを見ながら歩くのは危ないですよ。','アルバイトをしながら大学に通っています。']::text[], extra_examples_vi = ARRAY['Vừa nhìn điện thoại vừa đi bộ thì nguy hiểm đấy.','Tôi vừa đi làm thêm vừa học đại học.']::text[], memory_tip = 'ながら nối vào thể ます (bỏ ます), động từ chính luôn ở V2 — hành động phụ đứng trước, hành động chính đứng sau.', comparison_note = 'Khác Vて nối tiếp hai hành động theo thứ tự trước-sau, ながら diễn tả hai hành động xảy ra ĐỒNG THỜI.', common_mistake = 'Đảo ngược vị trí quan trọng của hai hành động — hành động chính (muốn nhấn mạnh) phải đặt ở V2, sau ながら, không phải trước.' where id = '34364521-91dd-59cd-a868-77c34cee80f7';
update grammar_points set extra_examples_jp = ARRAY['私は毎週日曜日に日本語を勉強しています。','弟は毎晩11時に寝ています。']::text[], extra_examples_vi = ARRAY['Tôi học tiếng Nhật vào mỗi Chủ nhật hàng tuần.','Em trai tôi ngủ lúc 11 giờ mỗi tối.']::text[], memory_tip = '~ています ở đây không phải ''đang làm'' mà là hành động lặp đi lặp lại thành thói quen — thường đi cùng từ chỉ tần suất (毎朝、毎週...).', comparison_note = 'Cùng hình thức ~ています nhưng khác nghĩa ''đang làm'' (hành động tức thời) — phân biệt qua có hay không có từ chỉ tần suất.', common_mistake = 'Nhầm ~ています chỉ thói quen với ~ています đang diễn ra ngay lúc nói khi câu thiếu từ chỉ tần suất làm rõ ngữ cảnh.' where id = '79105b52-ec1b-52fa-935e-36ea3be86cee';
update grammar_points set extra_examples_jp = ARRAY['ドアが開いています。','木の下に猫が座っています。']::text[], extra_examples_vi = ARRAY['Cửa đang mở.','Có một con mèo đang ngồi dưới gốc cây.']::text[], memory_tip = 'Đây là ''chụp lại'' hiện trạng trước mắt — dùng nội động từ (閉まる、開く、座る) đi cùng trợ từ が.', comparison_note = 'Khác Vて + あります (kết quả có chủ ý của ai đó, dùng ngoại động từ), mẫu này chỉ miêu tả khách quan trạng thái đang thấy.', common_mistake = 'Dùng nhầm ngoại động từ (開ける) thay vì nội động từ (開く) trong mẫu miêu tả trạng thái này — ドアが開けています là sai.' where id = 'fca1e355-ba2d-53b8-9f30-b46714da645b';
update grammar_points set extra_examples_jp = ARRAY['あの店は閉まっています。','この時計は止まっています。']::text[], extra_examples_vi = ARRAY['Cửa hàng đó đang đóng cửa.','Cái đồng hồ này đang bị dừng.']::text[], memory_tip = 'Khi vật đã biết rõ (có この/その/あの), đổi が thành は để làm chủ đề câu, giống như đang ''giới thiệu về'' vật đó.', comparison_note = 'So với Nが+Vています (lần đầu nêu ra, thường đi cùng câu hỏi 何が), Nは+Vています dùng khi vật đã được biết đến hoặc nhắc lại.', common_mistake = 'Dùng は cho một vật hoàn toàn mới, chưa được nhắc đến trước đó — trường hợp này phải dùng が để giới thiệu lần đầu.' where id = '0251e7b9-150f-5948-bdc1-d08c7fc3e248';
update grammar_points set extra_examples_jp = ARRAY['テーブルの上にコップが落ちています。','車の窓が汚れています。']::text[], extra_examples_vi = ARRAY['Có một cái cốc đang nằm trên bàn (do bị rơi trước đó).','Cửa kính xe đang bị bẩn.']::text[], memory_tip = 'Hành động đã xảy ra (ví dụ bật đèn) → giờ vẫn còn kết quả đó = Vています đi với nội động từ.', comparison_note = 'Gần giống mẫu miêu tả trạng thái nhưng nhấn mạnh trạng thái đó LÀ KẾT QUẢ của một hành động cụ thể đã xảy ra trước đó.', common_mistake = 'Nhầm với thì quá khứ đơn — dùng 電気がつきました để nói ''đèn đang bật'' là sai, phải dùng ています để chỉ trạng thái tiếp diễn.' where id = 'efd82dde-ee80-57bb-ad18-ec806abd8026';
update grammar_points set extra_examples_jp = ARRAY['大切な約束を忘れてしまいました。','電車の中でスマホを落としてしまいました。']::text[], extra_examples_vi = ARRAY['Tôi đã lỡ quên mất một lời hứa quan trọng.','Tôi đã lỡ làm rơi điện thoại trên tàu điện.']::text[], memory_tip = 'てしまいました nghĩa là ''lỡ làm mất/hỏng rồi'', mang cảm giác ''ôi, tiêu rồi!'' của người nói.', comparison_note = 'Khác てしまいます diễn tả việc SẼ hoàn thành trong tương lai, てしまいました luôn nói về việc ĐÃ xảy ra và gây tiếc nuối.', common_mistake = 'Dùng てしまいました cho những việc tích cực, đáng vui — mẫu này chỉ hợp với việc tiêu cực, ngoài ý muốn.' where id = '3f01068b-f881-5ffe-8138-0bab086485df';
update grammar_points set extra_examples_jp = ARRAY['今日中にこの本を全部読んでしまいます。','週末までに部屋を片付けてしまうつもりです。']::text[], extra_examples_vi = ARRAY['Tôi sẽ đọc xong hết cuốn sách này trong hôm nay.','Tôi định sẽ dọn xong phòng trước cuối tuần.']::text[], memory_tip = 'てしまいます ở nghĩa ''hoàn thành'' thường đi cùng mốc thời gian (までに) và もう/ぜんぶ để nhấn mạnh sự dứt điểm.', comparison_note = 'Cùng dạng てしまいます nhưng mang nghĩa tích cực về sự hoàn tất, trái với sắc thái tiếc nuối của てしまいました.', common_mistake = 'Chỉ dựa vào thì để phân biệt hai nghĩa của てしまいます — thực ra cần dựa vào ngữ cảnh (có mốc thời gian tương lai hay không) để phân biệt nghĩa hoàn thành và nghĩa tiếc nuối.' where id = '3da15ef5-17a9-5c57-9b7d-dc6f9275d989';
update grammar_points set extra_examples_jp = ARRAY['探していた鍵、かばんの中にありました。','あ、なくしたと思っていた本、ここにありました。']::text[], extra_examples_vi = ARRAY['Cái chìa khóa tôi đang tìm, hóa ra nằm trong cặp.','À, cuốn sách tôi tưởng bị mất, hóa ra ở đây rồi.']::text[], memory_tip = '~ありました dùng đúng khoảnh khắc ''tìm thấy'' — thường có あ đứng đầu câu để thể hiện sự bất ngờ, mừng rỡ.', comparison_note = 'Khác ~があります (đơn thuần nói có tồn tại vật gì đó), ~ありました mang sắc thái phát hiện lại một vật đã bị thất lạc trước đó.', common_mistake = 'Dùng thì hiện tại ~があります thay vì quá khứ ~ありました khi diễn tả khoảnh khắc vừa tìm thấy, làm mất đi sắc thái bất ngờ, vui mừng.' where id = 'd4d44152-6b4d-587a-8070-d89129cf6460';
update grammar_points set extra_examples_jp = ARRAY['どこかで会ったことがある人だと思います。','傘をどこかに置き忘れてしまいました。']::text[], extra_examples_vi = ARRAY['Tôi nghĩ đó là người mình đã từng gặp ở đâu đó.','Tôi đã bỏ quên cái ô ở đâu đó rồi.']::text[], memory_tip = 'どこか nghĩa là ''đâu đó'' (không xác định); で đi với hành động, に đi với vị trí tồn tại.', comparison_note = 'Khác どこ (từ nghi vấn hỏi cụ thể địa điểm), どこか mang tính bất định, không cần biết rõ nơi chốn.', common_mistake = 'Lược bỏ trợ từ で/に sau どこか — khác với へ/を có thể bỏ được, で và に trong どこかで/どこかに là bắt buộc, không được lược bỏ.' where id = '6316114b-feb5-5d92-b637-c2368cb74a2f';
update grammar_points set extra_examples_jp = ARRAY['冷蔵庫にジュースが入れてあります。','玄関に花が飾ってあります。']::text[], extra_examples_vi = ARRAY['Trong tủ lạnh có nước ép được để sẵn.','Ở lối vào có hoa được cắm trang trí sẵn.']::text[], memory_tip = 'N1に N2が Vてあります: ''ở đâu (に) có cái gì (が) đã được ai đó chuẩn bị sẵn (て)'' — luôn dùng ngoại động từ.', comparison_note = 'Khác Nが+Vています (chỉ miêu tả khách quan, dùng nội động từ), mẫu てあります luôn hàm ý CÓ NGƯỜI đã chủ ý làm việc đó.', common_mistake = 'Dùng nội động từ thay vì ngoại động từ trong mẫu này — ví dụ 窓が開いてあります là sai, phải dùng ngoại động từ như 開けてあります.' where id = '133a89ad-0458-503f-b145-331efcbf4ee4';
update grammar_points set extra_examples_jp = ARRAY['会議室の資料はもう準備してあります。','今晩のパーティーの料理はもう作ってあります。']::text[], extra_examples_vi = ARRAY['Tài liệu cho phòng họp thì đã được chuẩn bị sẵn rồi.','Món ăn cho bữa tiệc tối nay thì đã được nấu sẵn rồi.']::text[], memory_tip = 'Khi vật (N2) đã biết rõ, đưa lên đầu câu làm chủ đề bằng は, thường đi kèm もう để nhấn mạnh ''đã chuẩn bị xong từ trước''.', comparison_note = 'Phân biệt rõ: ~ています đi với NỘI động từ (miêu tả trạng thái đơn thuần), còn ~てあります đi với NGOẠI động từ (kết quả có chủ ý).', common_mistake = 'Quên đổi trợ từ が thành は khi vật đã trở thành chủ đề quen thuộc trong hội thoại, khiến câu nghe cộc và không tự nhiên.' where id = 'cecfc982-d135-5f16-b76a-9bf2a83704f4';
update grammar_points set extra_examples_jp = ARRAY['テーブルにお茶が入れてあります。どうぞ飲んでください。','机の上にメモが置いてあります。']::text[], extra_examples_vi = ARRAY['Trên bàn có trà đã được rót sẵn. Mời anh uống.','Trên bàn có một mảnh giấy ghi chú được để sẵn.']::text[], memory_tip = 'Vてあります = trạng thái đang tồn tại NHỜ có ai đó chủ ý làm trước — luôn nghĩ đến ''bàn tay con người'' đứng sau.', comparison_note = 'Khác Vています (trạng thái tự nhiên, khách quan), Vてあります luôn ngầm hiểu có người đã chuẩn bị hoặc sắp đặt trước đó với mục đích nào đó.', common_mistake = 'Nhầm chủ thể hành động — Vてあります không nêu rõ AI đã làm (không dùng で để chỉ người thực hiện), khác với câu bị động thông thường.' where id = 'e5854aea-8b85-5c29-ab33-8b147335bdfd';
update grammar_points set extra_examples_jp = ARRAY['会議の前に資料をコピーしておきます。','飲み物は冷蔵庫に入れておいてください。']::text[], extra_examples_vi = ARRAY['Trước cuộc họp, tôi sẽ photocopy tài liệu trước.','Xin hãy để đồ uống vào tủ lạnh sẵn giúp tôi.']::text[], memory_tip = 'ておきます nghĩa là ''làm trước để sẵn sàng cho sau'' — nhớ お trong おきます giống ''đặt trước, chuẩn bị trước''.', comparison_note = 'Khác てあります (kết quả trạng thái đã hoàn thành), ておきます nhấn mạnh HÀNH ĐỘNG chuẩn bị trước, thường dùng ở thì tương lai hoặc ý định.', common_mistake = 'Nhầm ておきます với てしまいます — cả hai đều có sắc thái ''hoàn tất'' nhưng ておきます mang mục đích chuẩn bị cho tương lai, còn てしまいます nhấn mạnh sự dứt điểm hoặc tiếc nuối.' where id = '01e5b11e-5d8a-5f50-add2-941a977b0bf4';
update grammar_points set extra_examples_jp = ARRAY['「来月結婚するんです。」「それはおめでとうございます。」','「財布をなくしてしまいました。」「それは大変ですね。」']::text[], extra_examples_vi = ARRAY['Tháng sau tôi kết hôn đấy. Vậy thì xin chúc mừng anh.','Tôi bị mất ví rồi. Vậy thì vất vả quá nhỉ.']::text[], memory_tip = 'それ ở đây không chỉ một vật cụ thể mà chỉ NGUYÊN CÂU đối phương vừa nói — dùng để phản hồi nhanh.', comparison_note = 'Khác これ (chỉ điều người nói sắp nói hoặc đang cầm), それ trong hội thoại dùng để chỉ lại nội dung đối phương VỪA nói.', common_mistake = 'Dùng これ thay vì それ khi phản hồi lời người khác vừa nói — これ chỉ dùng cho vật hoặc điều thuộc về phía người nói.' where id = 'f527080b-af2b-57a4-a0ad-13c6b60befc2';
update grammar_points set extra_examples_jp = ARRAY['弟はまだ寝ています。','子供はまだ小さいです。一人で電車に乗れません。']::text[], extra_examples_vi = ARRAY['Em trai tôi vẫn còn đang ngủ.','Đứa trẻ vẫn còn nhỏ. Nó không thể tự đi tàu điện một mình.']::text[], memory_tip = 'まだ + khẳng định = ''vẫn còn'' (tiếp diễn); まだ + phủ định = ''vẫn chưa'' (chưa xảy ra) — nhớ phân biệt theo vế sau.', comparison_note = 'Đối lập trực tiếp với まだ + Vていません — cùng まだ nhưng khẳng định là ''vẫn đang'', phủ định là ''vẫn chưa''.', common_mistake = 'Nhầm lẫn nghĩa まだ giữa câu khẳng định và phủ định — chỉ nhìn thấy まだ mà không để ý thể của động từ phía sau dễ hiểu sai hoàn toàn nghĩa câu.' where id = '0a0b88f4-f9e1-5077-a391-a9d973009a8b';
update grammar_points set extra_examples_jp = ARRAY['来週、大阪へ出張する予定です。','会議は午後3時から始まる予定です。']::text[], extra_examples_vi = ARRAY['Tuần sau, tôi có dự định đi công tác Osaka.','Cuộc họp dự kiến bắt đầu từ 3 giờ chiều.']::text[], memory_tip = 'よてい là kế hoạch đã được SẮP XẾP, LÊN LỊCH sẵn (khách quan), khác với ý định cá nhân chưa chắc chắn.', comparison_note = 'Khác つもり (ý định chủ quan của cá nhân, chưa chắc thành hiện thực), よてい mang tính khách quan hơn, thường dùng cho lịch trình đã định.', common_mistake = 'Dùng よてい cho ý định cá nhân bộc phát, chưa có kế hoạch cụ thể — trường hợp này nên dùng つもり hoặc とおもっています mới đúng sắc thái.' where id = 'd4d342af-d9ef-5fff-9857-449504828bd4';
update grammar_points set extra_examples_jp = ARRAY['そろそろ帰ろう。','今度の休みに、みんなで温泉に行こう。']::text[], extra_examples_vi = ARRAY['Về thôi, sắp đến giờ rồi.','Kỳ nghỉ tới, cả nhóm mình cùng đi suối nước nóng nhé.']::text[], memory_tip = 'Thể ý định là cách nói ''rủ rê'' thân mật, giống ~ましょう nhưng suồng sã hơn, dùng với bạn bè, người thân.', comparison_note = 'Vai trò tương đương ~ましょう (lịch sự) nhưng thể ý định (意向形) chỉ dùng trong văn nói thân mật, suồng sã, hoặc nói với chính mình.', common_mistake = 'Dùng thể ý định với người trên hoặc người không thân quen — sẽ nghe bất lịch sự, nên dùng ~ましょう trong ngữ cảnh trang trọng.' where id = '209e82db-8ba1-58ca-81ec-9ca6bf6321e5';
update grammar_points set extra_examples_jp = ARRAY['来年、日本へ留学しようと思っています。','田中さんは会社を辞めようと思っているそうです。']::text[], extra_examples_vi = ARRAY['Sang năm, tôi đang định đi du học Nhật Bản.','Nghe nói anh Tanaka đang có ý định nghỉ việc ở công ty.']::text[], memory_tip = 'とおもっています (đang nghĩ) khác とおもいます (nghĩ ngay lúc nói) — ています cho thấy ý định đã có từ trước và vẫn đang duy trì.', comparison_note = 'So với つもりです (dứt khoát, chắc chắn hơn), とおもっています mang sắc thái ý định còn linh hoạt, có thể thay đổi.', common_mistake = 'Dùng とおもいます (không có ています) để nói về ý định đã có từ lâu — とおもいます chỉ diễn tả suy nghĩ NGAY tại thời điểm nói, không phù hợp cho ý định lâu dài.' where id = '7b6ed5b5-ea6a-5105-a0cb-d9e1cd47ea5b';
update grammar_points set extra_examples_jp = ARRAY['今年こそ、絶対に日本語能力試験に合格するつもりです。','もう彼とは会わないつもりです。']::text[], extra_examples_vi = ARRAY['Năm nay, tôi quyết tâm nhất định sẽ đỗ kỳ thi năng lực tiếng Nhật.','Tôi quyết định sẽ không gặp anh ấy nữa.']::text[], memory_tip = 'つもり là quyết định chắc chắn trong đầu — thể từ điển dùng cho ''sẽ làm'', thể ない dùng cho ''sẽ không làm''.', comparison_note = 'Quyết đoán, dứt khoát hơn とおもっています; cũng khác よてい ở chỗ つもり mang tính chủ quan, cá nhân, chưa chắc được sắp xếp thành lịch trình cụ thể.', common_mistake = 'Dùng thể ます thay vì thể từ điển hoặc thể ない trước つもりです — phải dùng đúng thể từ điển/ない, không dùng thể ます.' where id = '88812a45-0959-58f5-8454-542f5789826c';
update grammar_points set extra_examples_jp = ARRAY['今日の宿題はまだ終わっていません。','彼にはまだ連絡していません。']::text[], extra_examples_vi = ARRAY['Bài tập về nhà hôm nay vẫn chưa xong.','Tôi vẫn chưa liên lạc với anh ấy.']::text[], memory_tip = 'まだ~ていません nghĩa là ''vẫn chưa'' — luôn đi cùng cặp với まだ + khẳng định (vẫn đang) để phân biệt rõ.', comparison_note = 'Đối lập với まだ+Vています (''vẫn đang tiếp diễn''), mẫu này là ''vẫn chưa xảy ra'', cũng khác với もう~ました (đã xong rồi).', common_mistake = 'Dùng まだ + Vません (phủ định thường) thay vì まだ + Vていません — mẫu đúng phải ở dạng ています phủ định để nhấn mạnh ''tính đến giờ vẫn chưa''.' where id = '245b3509-b409-53fa-98cd-eb2290cbad65';
update grammar_points set extra_examples_jp = ARRAY['このアパートは家賃5万円で借りられます。','1時間で宿題が全部終わりました。']::text[], extra_examples_vi = ARRAY['Căn hộ này có thể thuê được với giá 5 vạn yên.','Trong vòng 1 tiếng tôi đã làm xong hết bài tập.']::text[], memory_tip = 'で sau lượng từ (tiền/thời gian) nghĩa là ''chỉ với/trong mức đó'' — giới hạn cần thiết để làm được việc gì.', comparison_note = 'Khác で chỉ phương tiện hoặc địa điểm thông thường, で sau lượng từ mang nghĩa ''phạm vi/giới hạn đủ để'', thường đi cùng động từ khả năng.', common_mistake = 'Nhầm で giới hạn với に thời điểm — で ở đây chỉ MỨC/KHOẢNG cần để hoàn thành, không phải mốc thời gian cụ thể.' where id = '259db7b3-8dac-5927-8fcb-aa6c7317b2a4';
update grammar_points set extra_examples_jp = ARRAY['田中さんは今日、会社を休むかもしれません。','この店、もう閉まっているかもしれません。']::text[], extra_examples_vi = ARRAY['Có thể hôm nay anh Tanaka nghỉ làm cũng nên.','Cửa hàng này có lẽ đã đóng cửa rồi cũng nên.']::text[], memory_tip = 'かもしれません nghĩa là ''có thể... cũng nên'', mức độ chắc chắn THẤP nhất trong các mẫu phỏng đoán.', comparison_note = 'Mức độ chắc chắn thấp hơn hẳn でしょう — かもしれません dùng khi khả năng xảy ra dưới 50%, còn không chắc chắn lắm.', common_mistake = 'Dùng かもしれません cho những việc gần như chắc chắn xảy ra (nên dùng でしょう) — làm câu nghe thiếu tự tin không cần thiết.' where id = 'c9b3c3d1-eb33-5ec1-b16d-6e6e8848d3aa';
update grammar_points set extra_examples_jp = ARRAY['田中さんはもう帰ったでしょう。','来年、物価はもっと高くなるでしょう。']::text[], extra_examples_vi = ARRAY['Chắc là anh Tanaka đã về rồi.','Sang năm, chắc là vật giá sẽ còn tăng cao hơn.']::text[], memory_tip = 'でしょう là suy đoán có căn cứ, độ tin cậy cao hơn かもしれません nhưng vẫn không khẳng định chắc như です.', comparison_note = 'Độ chắc chắn cao hơn かもしれません nhưng thấp hơn はず (dựa trên căn cứ logic chặt chẽ); khi lên giọng cuối câu còn dùng để hỏi xác nhận nhẹ nhàng.', common_mistake = 'Quên bỏ だ của danh từ và tính từ đuôい な ở thể thông thường trước でしょう — 元気だでしょう là sai, phải là 元気でしょう.' where id = '2e978ead-c1a4-502b-b3f7-2b388666aa5a';
update grammar_points set extra_examples_jp = ARRAY['体の調子が悪いなら、病院へ行ったほうがいいですよ。','夜、コーヒーを飲まないほうがいいです。']::text[], extra_examples_vi = ARRAY['Nếu thấy người không khỏe thì nên đi bệnh viện đấy.','Buổi tối thì không nên uống cà phê.']::text[], memory_tip = 'Nên làm dùng V thể た + ほうがいい; không nên làm dùng Vない + ほうがいい — luôn nhớ ''khuyên bằng thể た hoặc ない'', không dùng thể từ điển.', comparison_note = 'Là lời khuyên trực tiếp, đơn giản hơn かもしれません/でしょう (chỉ là phỏng đoán) — ほうがいい luôn hàm ý khuyên nhủ rõ ràng.', common_mistake = 'Dùng thể từ điển thay vì thể た khi khuyên nên làm — 運動するほうがいい nghe kém tự nhiên hơn 運動したほうがいい, cần chú ý dùng đúng thể た.' where id = '4a3eaf12-e64e-5383-8720-1be154463261';
update grammar_points set extra_examples_jp = ARRAY['彼はまじめだから、きっと試験に合格するでしょう。','たぶん明日の会議には間に合うと思います。']::text[], extra_examples_vi = ARRAY['Vì anh ấy nghiêm túc nên chắc chắn sẽ đỗ kỳ thi thôi.','Chắc là tôi sẽ kịp cuộc họp ngày mai.']::text[], memory_tip = 'Xếp theo độ chắc chắn giảm dần: きっと (chắc chắn, khoảng 90%) hơn たぶん (khá chắc, khoảng 70%) hơn もしかしたら (có thể, dưới 50%).', comparison_note = 'Ba trạng từ này thường đi kèm でしょう/とおもいます (きっと、たぶん) hoặc かもしれません (もしかしたら) để khớp mức độ chắc chắn.', common_mistake = 'Dùng きっと đi cùng かもしれません — sai vì きっと biểu thị độ chắc chắn cao trong khi かもしれません biểu thị độ chắc chắn thấp, hai từ mâu thuẫn nhau.' where id = '0ecb20f0-14ee-59d5-bd6b-3a21683881b3';
update grammar_points set extra_examples_jp = ARRAY['先生は学生に「静かにしろ」と言いました。','危ない、逃げろ！']::text[], extra_examples_vi = ARRAY['Thầy giáo đã nói với học sinh rằng "Hãy im lặng".','Nguy hiểm, chạy đi!']::text[], memory_tip = 'Nhớ thể mệnh lệnh giống như "quát" chứ không phải "nhờ" — chỉ dùng khi thật sự cần ra lệnh gấp hoặc thân mật.', comparison_note = 'Khác Vてください (yêu cầu lịch sự, dùng được với người lạ, cấp trên) — thể mệnh lệnh/cấm chỉ chỉ hợp với quan hệ trên dưới hoặc tình huống khẩn cấp.', common_mistake = 'Dùng thể mệnh lệnh với khách hàng, cấp trên hoặc người mới quen sẽ bị coi là bất lịch sự, thậm chí xúc phạm.' where id = '252a042d-7663-5dd0-b851-2385f9f709a2';
update grammar_points set extra_examples_jp = ARRAY['「MTG」はミーティングという意味です。','この矢印は立入禁止という意味ですか。']::text[], extra_examples_vi = ARRAY['"MTG" có nghĩa là cuộc họp.','Mũi tên này có nghĩa là cấm vào phải không?']::text[], memory_tip = 'Nhớ という意味です như cụm cố định để giải thích nghĩa của một từ/ký hiệu, giống như nói "nghĩa là...".', comparison_note = 'Khác ~と読みます/~と書きます (hỏi cách đọc/cách viết) — という意味です hỏi về Ý NGHĨA, không phải cách phát âm hay chữ viết.', common_mistake = 'Nhầm という意味です với と言います khi muốn hỏi nghĩa; と言います chỉ dùng để hỏi cách gọi tên một vật bằng tiếng Nhật, không phải giải thích nghĩa.' where id = 'd891bbd5-3301-5b17-8ddd-ac8c849daf69';
update grammar_points set extra_examples_jp = ARRAY['電車の中で電話をするな。','もっと野菜を食べろ。']::text[], extra_examples_vi = ARRAY['Không được gọi điện thoại trong tàu điện.','Ăn nhiều rau hơn đi.']::text[], memory_tip = 'Nhớ quy tắc theo nhóm động từ: nhóm 1 đổi sang hàng え, nhóm 2 thêm ろ, nhóm 3 học thuộc riêng (こい, しろ); cấm chỉ thì luôn thêm な vào thể từ điển, không cần đổi dạng.', comparison_note = 'Khác thể ý chí (意向形) dùng để rủ rê/quyết tâm — thể mệnh lệnh dùng để ra lệnh, còn cấm chỉ (+な) dùng để cấm đoán.', common_mistake = 'Nhầm な cấm chỉ (thêm sau thể từ điển) với な trong tính từ な hoặc trợ từ な cuối câu diễn tả cảm thán — về hình thức giống nhau nhưng chức năng hoàn toàn khác.' where id = 'bc6aef63-a54f-58a2-82b4-e4b1b6c7934f';
update grammar_points set extra_examples_jp = ARRAY['部長に、会議が中止になったと伝えていただけませんか。','先生に、レポートを来週出すと伝えていただけませんか。']::text[], extra_examples_vi = ARRAY['Anh có thể nhắn với trưởng phòng rằng cuộc họp đã bị hủy được không?','Thầy có thể nhắn giúp em rằng tuần sau em sẽ nộp báo cáo được không ạ?']::text[], memory_tip = 'Nhớ cấu trúc = nội dung cần nhắn (thể thông thường) + と + 伝えていただけませんか (nhờ truyền đạt hộ, cực kỳ lịch sự).', comparison_note = 'Khác Vていただけませんか thông thường (nhờ trực tiếp làm gì đó) — cấu trúc này chuyên dùng cho việc NHỜ NHẮN LẠI lời nói cho người thứ ba.', common_mistake = 'Quên đổi nội dung cần nhắn sang thể thông thường trước と — ví dụ không thể nói ですと伝えて, danh từ/tính từ な phải thêm だ ở thể thông thường.' where id = 'd441420b-f0c0-5ef9-846d-219a7eae2213';
update grammar_points set extra_examples_jp = ARRAY['山田さんはもうすぐ着くと言っていました。','母は今日遅く帰ると言っていました。']::text[], extra_examples_vi = ARRAY['Anh Yamada nói là sắp đến nơi rồi.','Mẹ tôi nói hôm nay sẽ về muộn.']::text[], memory_tip = 'と言っていました = "đã nói rằng..." dùng để TRUYỀN ĐẠT LẠI ý người khác, không nhất thiết đúng nguyên văn từng chữ.', comparison_note = 'Khác trích dẫn nguyên văn 「...」といいました (giữ nguyên lời nói, kể cả ngôi xưng) — と言っていました có thể đổi ngôi, đổi cách diễn đạt miễn giữ đúng nội dung.', common_mistake = 'Quên chuyển câu trích dẫn sang thể thông thường trước と — ví dụ không nói 忙しいですと言っていました mà phải là 忙しいと言っていました.' where id = 'bf5d192b-fa3f-5132-a727-8ea7dcac3669';
update grammar_points set extra_examples_jp = ARRAY['この字は何と読みますか。','「ありがとう」はひらがなで何と書きますか。']::text[], extra_examples_vi = ARRAY['Chữ này đọc là gì vậy?','"Arigatou" viết bằng hiragana như thế nào?']::text[], memory_tip = '読みます = đọc, 書きます = viết; nhớ theo cặp と読みますか (hỏi cách đọc) / と書きますか (hỏi cách viết).', comparison_note = 'Khác N1は N2という意味です (hỏi Ý NGHĨA) — と読みますか/と書きますか chỉ hỏi về CÁCH PHÁT ÂM hoặc CÁCH VIẾT, không hỏi nghĩa.', common_mistake = 'Dùng nhầm と読みますか khi thực ra muốn hỏi nghĩa của từ — phải dùng という意味ですか mới đúng.' where id = 'bdabc79b-f9cd-5fe6-b98a-e82ae40927bf';
update grammar_points set extra_examples_jp = ARRAY['先生が話したとおりに、みんな行動しました。','地図のとおりに歩いたら、駅に着きました。']::text[], extra_examples_vi = ARRAY['Mọi người đã hành động đúng theo những gì thầy giáo nói.','Tôi đã đi đúng theo bản đồ và đến được nhà ga.']::text[], memory_tip = 'とおり viết giống 通り (con đường) — hiểu là "đi đúng con đường/cách đã chỉ", không lệch.', comparison_note = 'Khác ~まま (giữ nguyên trạng thái không đổi) — とおりに nhấn mạnh làm ĐÚNG THEO một khuôn mẫu, hướng dẫn có sẵn.', common_mistake = 'Dùng thể từ điển cho hành động đã xảy ra rồi — nếu nói về việc đã biết/đã xảy ra phải dùng Vた (説明したとおりに), chỉ dùng thể từ điển cho việc sắp làm hoặc quy luật chung.' where id = 'c242364a-ea52-5150-8d18-659791d681bf';
update grammar_points set extra_examples_jp = ARRAY['宿題をしたあとで、ゲームをしてもいいですよ。','食事のあとで、薬を飲んでください。']::text[], extra_examples_vi = ARRAY['Sau khi làm xong bài tập thì con chơi game cũng được.','Sau bữa ăn thì hãy uống thuốc nhé.']::text[], memory_tip = 'あとで = "sau đó"; luôn đi với Vた (đã xong) hoặc Nの, không dùng thể từ điển.', comparison_note = 'Khác ~てから (cũng chỉ trình tự nhưng nhấn mạnh hành động sau bắt đầu ngay khi hành động trước kết thúc) — あとで chỉ đơn thuần nêu thứ tự trước sau, không nhấn mạnh tính liên tục.', common_mistake = 'Dùng nhầm thể từ điển thay vì Vた trước あとで — phải nói 食べたあとで chứ không phải 食べるあとで.' where id = '53f8145c-c986-5b96-b71f-118bcb479e1f';
update grammar_points set extra_examples_jp = ARRAY['窓を開けて、空気を入れ替えました。','傘を持たないで、出かけてしまいました。']::text[], extra_examples_vi = ARRAY['Tôi mở cửa sổ và thay đổi không khí.','Tôi đã ra ngoài mà không mang ô.']::text[], memory_tip = 'Vて = kèm theo/vừa làm vừa, Vないで = KHÔNG làm mà vẫn làm V2 tiếp — chú ý で ở cuối để phân biệt với Vないと (nếu không...).', comparison_note = 'Khác Vずに (văn viết, trang trọng hơn, cùng nghĩa với Vないで) — trong hội thoại hàng ngày dùng Vないで phổ biến hơn.', common_mistake = 'Nhầm Vないで (không làm mà) với Vなくて (nguyên nhân, kết quả tiêu cực) — hai cấu trúc khác chức năng dù hình thức gần giống.' where id = '008acea1-975e-5036-b9fe-ade248c34720';
update grammar_points set extra_examples_jp = ARRAY['今日は勉強しないで、映画を見に行きます。','朝ご飯を食べないで、会社へ行きました。']::text[], extra_examples_vi = ARRAY['Hôm nay tôi không học mà đi xem phim.','Tôi đã đi làm mà không ăn sáng.']::text[], memory_tip = 'Đây là dạng đặc biệt của Vないで — mang nghĩa "chọn không làm V1, mà làm V2 thay vào đó" chứ không phải "vừa không làm vừa làm".', comparison_note = 'Khác Vて V2 thông thường (hai hành động cùng xảy ra hoặc nối tiếp) — Vないで、V2 mang tính LỰA CHỌN, loại trừ lẫn nhau.', common_mistake = 'Nhầm với ~ずに (mang tính trang trọng, văn viết) rồi dùng sai trong văn nói thân mật — trong hội thoại nên ưu tiên Vないで.' where id = 'ea58fc27-64c0-5897-af8a-ddf44249f49f';
update grammar_points set extra_examples_jp = ARRAY['薬を飲めば、すぐ元気になりますよ。','この道をまっすぐ行けば、駅があります。']::text[], extra_examples_vi = ARRAY['Nếu uống thuốc thì sẽ khỏe lại ngay thôi.','Nếu đi thẳng theo con đường này thì sẽ thấy nhà ga.']::text[], memory_tip = 'ば = "nếu" mang tính điều kiện tổng quát, khách quan — hợp để nói về quy luật, chỉ đường, lời khuyên chung chung.', comparison_note = 'Khác たら (linh hoạt hơn, dùng được cả khi vế sau là mệnh lệnh, ý chí) — ば hạn chế hơn về ngữ pháp vế sau.', common_mistake = 'Dùng ば khi vế sau là mệnh lệnh/rủ rê có chủ ngữ giống vế trước — trường hợp này phải dùng たら, ví dụ không nói 暇ならば来てください mà nói 暇だったら来てください.' where id = '4a2eb72d-ee35-5d60-ad32-40d73c8db400';
update grammar_points set extra_examples_jp = ARRAY['急げば、間に合います。','静かなら、ここで勉強してもいいです。']::text[], extra_examples_vi = ARRAY['Nếu nhanh lên thì sẽ kịp giờ.','Nếu yên tĩnh thì học ở đây cũng được.']::text[], memory_tip = 'Nhớ mẹo: hàng え + ば cho nhóm 1 (書く→書けば), bỏ ます thêm れば cho nhóm 2, tính từ い đổi い→ければ, danh từ/な-tính từ thêm なら.', comparison_note = 'Khác cách tạo thể たら (thêm ら vào Vた) — hai thể điều kiện có cách chia hoàn toàn khác nhau nên dễ nhầm khi mới học.', common_mistake = 'Chia sai động từ nhóm 2 bằng cách giữ nguyên đuôい rồi thêm ければ (kiểu tính từ) — động từ nhóm 2 phải bỏ ます rồi thêm れば, ví dụ 食べれば chứ không phải 食べければ.' where id = 'bf84a3a2-4384-5bfa-9c8a-c6a1901e7f52';
update grammar_points set extra_examples_jp = ARRAY['天気がよければ、富士山が見えます。','薬を飲めば、熱が下がるはずです。']::text[], extra_examples_vi = ARRAY['Nếu thời tiết đẹp thì có thể nhìn thấy núi Phú Sĩ.','Nếu uống thuốc thì chắc là sốt sẽ hạ.']::text[], memory_tip = 'Nhớ ば chỉ hợp với vế sau KHÔNG mang ý chí — nếu muốn ra lệnh/rủ rê/quyết định ở vế sau, hãy chuyển sang dùng たら.', comparison_note = 'Khác たら (không bị giới hạn này, dùng được cả khi vế sau là mệnh lệnh hoặc ý chí) — vì vậy たら linh hoạt và phổ biến hơn trong hội thoại.', common_mistake = 'Nói 安ければ、買ってください (sai) thay vì 安かったら、買ってください (đúng) — vì vế sau là mệnh lệnh nên không dùng được ば.' where id = 'b2f93767-b00a-5bdf-941d-4128f2d4da13';
update grammar_points set extra_examples_jp = ARRAY['春になると、桜が咲きます。','駅に着いたら、電話してください。']::text[], extra_examples_vi = ARRAY['Cứ đến mùa xuân là hoa anh đào lại nở.','Khi nào đến ga thì hãy gọi điện cho tôi nhé.']::text[], memory_tip = 'Xếp theo độ tự do vế sau: と (chặt nhất, chỉ kết quả tất yếu) < ば (hạn chế mệnh lệnh/ý chí) < たら (tự do nhất, dùng được hầu hết mọi trường hợp).', comparison_note = 'Khác Hạn chế của thể điều kiện ば (giải thích riêng về giới hạn của ば) — mục này so sánh tổng quát cả ba thể điều kiện với nhau.', common_mistake = 'Dùng と cho việc chỉ xảy ra một lần trong quá khứ với ý chủ định — と chỉ hợp với quy luật lặp lại hoặc kết quả tất yếu, không hợp với hành động đơn lẻ có chủ ý.' where id = '08846468-b57f-5ed4-8835-358132d90f6f';
update grammar_points set extra_examples_jp = ARRAY['駅までどう行けばいいですか。','何時に来ればいいですか。']::text[], extra_examples_vi = ARRAY['Đi đến nhà ga thì phải đi thế nào ạ?','Tôi nên đến lúc mấy giờ ạ?']::text[], memory_tip = 'Cấu trúc = từ nghi vấn (どう/何/いつ...) + Vば + いいですか, dùng khi cần lời khuyên hoặc chỉ dẫn cụ thể.', comparison_note = 'Khác どうしたらいいですか (dùng たら, đã học ở N5) — hai cách nói cùng nghĩa, có thể thay thế cho nhau, たら phổ biến trong khẩu ngữ hơn.', common_mistake = 'Quên từ nghi vấn ở đầu câu rồi chỉ hỏi Vばいいですか — nếu không có từ nghi vấn thì câu chỉ còn nghĩa "làm vậy có tốt không" chứ không phải hỏi cách làm.' where id = '0657e35c-2b40-56ec-9362-0c0706174b27';
update grammar_points set extra_examples_jp = ARRAY['練習すればするほど、上手になります。','この本は読めば読むほど面白いです。']::text[], extra_examples_vi = ARRAY['Càng luyện tập thì càng giỏi lên.','Cuốn sách này càng đọc càng thấy thú vị.']::text[], memory_tip = 'Nhớ mẫu lặp động từ: Vば + V(từ điển)ほど — ví dụ 飲めば飲むほど (càng uống càng...).', comparison_note = 'Khác ~につれて (diễn tả xu hướng thay đổi song song nhưng không nhấn mạnh mức độ tương ứng rõ như ば～ほど).', common_mistake = 'Dùng hai động từ khác nhau ở hai vế thay vì lặp lại cùng một động từ — cấu trúc chuẩn phải lặp cùng một từ (すればするほど), không phải すればいいほど.' where id = '38b5e1c9-1707-5c2a-912c-67023edf7026';
update grammar_points set extra_examples_jp = ARRAY['健康のために、野菜をたくさん食べるようにしています。','会議に遅れないようにしてください。']::text[], extra_examples_vi = ARRAY['Vì sức khỏe, tôi cố gắng ăn nhiều rau.','Xin hãy cố gắng đừng đến muộn cuộc họp.']::text[], memory_tip = 'しています = đang duy trì cố gắng (thói quen bản thân), してください = nhờ người khác cố gắng — cùng gốc ように nhưng khác chủ thể cố gắng.', comparison_note = 'Khác V(khả năng/vô ý)ように (diễn tả MỤC ĐÍCH của hành động khác) — ようにしています/してください tập trung vào sự CỐ GẮNG DUY TRÌ, không phải mục đích của một hành động khác.', common_mistake = 'Dùng ようにしています cho việc chỉ làm một lần, không phải thói quen — cấu trúc này chỉ hợp khi nói về nỗ lực LẶP LẠI, DUY TRÌ theo thời gian.' where id = '66b0cb48-bc58-5225-b377-54ac6403585e';
update grammar_points set extra_examples_jp = ARRAY['練習して、自転車に乗れるようになりました。','漢字が少しずつ読めるようになりました。']::text[], extra_examples_vi = ARRAY['Sau khi luyện tập, tôi đã có thể đi xe đạp được.','Tôi đã dần dần đọc được chữ Hán.']::text[], memory_tip = 'なりました = "đã trở nên" — nhấn mạnh sự THAY ĐỔI theo thời gian, không phải trạng thái ngay từ đầu.', comparison_note = 'Khác V + ようになります (chưa hoàn thành, đang trong quá trình hoặc dự đoán) — ようになりました khẳng định sự thay đổi ĐÃ XẢY RA.', common_mistake = 'Dùng động từ thường thay vì thể khả năng trước ようになりました — phải chia động từ ở dạng khả năng trước, ví dụ 話せるようになりました chứ không phải 話すようになりました.' where id = '0eda1c8d-4954-57f7-881f-aff2e3302513';
update grammar_points set extra_examples_jp = ARRAY['忘れないように、メモを取ります。','みんなに聞こえるように、大きい声で話しました。']::text[], extra_examples_vi = ARRAY['Để không quên, tôi ghi chú lại.','Tôi đã nói to để mọi người có thể nghe thấy.']::text[], memory_tip = 'ように ở đây = "để cho" (mục đích), thường đi với động từ KHÔNG chủ ý như聞こえる, わかる, できる hoặc thể ない.', comparison_note = 'Khác ために (mục đích rõ ràng, chủ động, đi với động từ có ý chí) — ように đi với động từ vô ý/khả năng, ために đi với động từ ý chí.', common_mistake = 'Dùng động từ có ý chí trực tiếp trước ように mục đích — ví dụ không nói 勉強するように (sai khi muốn nói "để học"), phải dùng ために: 勉強するために.' where id = '3ce2910f-704e-5dcc-92a6-7caa279b5ffc';
update grammar_points set extra_examples_jp = ARRAY['冷蔵庫にはたまごとか、牛乳とか、いろいろ入っています。','休みの日は掃除をするとか、洗濯をするとかします。']::text[], extra_examples_vi = ARRAY['Trong tủ lạnh có nhiều thứ như trứng, sữa,...','Ngày nghỉ tôi hay làm việc như dọn dẹp, giặt giũ,...']::text[], memory_tip = 'とか mang tính khẩu ngữ, thoải mái — nhớ nó như "nào là... nào là..." trong tiếng Việt.', comparison_note = 'Khác や (liệt kê trang trọng hơn một chút, không lặp lại ở từ cuối) — とか có thể lặp cả sau từ cuối cùng trong danh sách.', common_mistake = 'Dùng とか trong văn viết trang trọng, báo cáo — とか chỉ phù hợp với văn nói thân mật, hội thoại hàng ngày.' where id = '047ae476-c9ce-597b-9e6d-9dcf7b96ed08';
update grammar_points set extra_examples_jp = ARRAY['彼は先生に注意されました。','その質問はよく聞かれます。']::text[], extra_examples_vi = ARRAY['Anh ấy đã bị thầy giáo nhắc nhở.','Câu hỏi đó thường được nhiều người hỏi.']::text[], memory_tip = 'Nhớ quy tắc: nhóm 1 đổi hàng い→あ +れます (書く→書かれる), nhóm 2 bỏ ます +られます (見る→見られる), nhóm 3 học thuộc (来る→来られる, する→される).', comparison_note = 'Khác thể khả năng (cũng chia られる cho nhóm 2, dễ nhầm hình thức) — bị động diễn tả bị/được tác động, khả năng diễn tả có thể làm được.', common_mistake = 'Nhầm られます của nhóm 2 bị động với られます thể khả năng — chỉ phân biệt được qua ngữ cảnh câu, ví dụ 食べられる có thể là "bị ăn" hoặc "có thể ăn được".' where id = 'cd26029b-6b0b-5a88-9165-0265a78c8c4e';
update grammar_points set extra_examples_jp = ARRAY['しょうゆは大豆から作られます。','この椅子は木で作られています。']::text[], extra_examples_vi = ARRAY['Xì dầu được làm từ đậu nành.','Chiếc ghế này được làm bằng gỗ.']::text[], memory_tip = 'から dùng khi nguyên liệu BIẾN ĐỔI hoàn toàn (không còn nhận ra hình dạng ban đầu), で dùng khi vật liệu vẫn GIỮ NGUYÊN hình dạng, nhận ra được ngay.', comparison_note = 'Khác N1は N2によって + V bị động (chỉ TÁC GIẢ/người tạo ra tác phẩm) — から/で chỉ NGUYÊN LIỆU/VẬT LIỆU, không phải người làm ra.', common_mistake = 'Dùng で cho nguyên liệu đã biến đổi hoàn toàn tính chất — ví dụ phải nói お酒は米から作られます (biến đổi), không nói お酒は米で作られます.' where id = 'f5fcd252-876e-55f9-b312-0c57076c092e';
update grammar_points set extra_examples_jp = ARRAY['オリンピックは4年に1度開催されます。','この寺は10世紀に建てられました。']::text[], extra_examples_vi = ARRAY['Thế vận hội được tổ chức 4 năm một lần.','Ngôi chùa này được xây dựng vào thế kỷ thứ 10.']::text[], memory_tip = 'Khi không cần biết/không quan trọng AI làm, chỉ nêu vật/việc làm chủ đề rồi dùng động từ bị động — không cần に người thực hiện.', comparison_note = 'Khác N1は N2に + V bị động (có nêu rõ đối tượng tác động lên N1) — dạng này thường KHÔNG nêu chủ thể vì không cần thiết hoặc không xác định.', common_mistake = 'Cố thêm に + người thực hiện dù câu vốn không cần nêu — với sự kiện mang tính khách quan, xã hội (tổ chức, xuất khẩu, xây dựng...) thường bỏ qua chủ thể mới tự nhiên.' where id = 'e3165370-a61d-5eeb-b857-c3f3040b30f9';
update grammar_points set extra_examples_jp = ARRAY['私は妹に日記を読まれました。','田中さんは部長に呼ばれました。']::text[], extra_examples_vi = ARRAY['Tôi đã bị em gái đọc trộm nhật ký.','Anh Tanaka đã được trưởng phòng gọi.']::text[], memory_tip = 'N1は N2に + V bị động = N1 chịu tác động TỪ N2 — に đứng trước động từ bị động chỉ RÕ người/vật gây ra tác động.', comparison_note = 'Khác N1は N2によって + V bị động (trang trọng, dùng cho tác phẩm/phát minh) — N2に dùng cho tác động thông thường trong đời sống, mang sắc thái cá nhân hơn.', common_mistake = 'Dùng によって cho tình huống đời thường nhỏ nhặt — によって nghe rất trang trọng, chỉ hợp khi nói về tác phẩm, phát minh, thành tựu lớn.' where id = 'acbf80cf-5615-53d7-91b0-a0acadc35ca4';
update grammar_points set extra_examples_jp = ARRAY['私は電車の中で隣の人に足を踏まれました。','弟に大切な本を破られました。']::text[], extra_examples_vi = ARRAY['Tôi đã bị người bên cạnh giẫm lên chân trong tàu điện.','Tôi đã bị em trai làm rách quyển sách quan trọng.']::text[], memory_tip = 'N3 luôn là bộ phận cơ thể hoặc đồ vật gắn liền với N1 (người bị hại) — nhớ thứ tự N1は N2に N3を + Vれる/られる.', comparison_note = 'Khác ~てもらいます (khi hành động đó giúp ích, đáng biết ơn) — nếu là việc phiền toái thì dùng bị động, nếu là việc được giúp đỡ thì dùng てもらいます.', common_mistake = 'Dùng bị động cho việc mình được giúp đỡ, biết ơn — ví dụ không nói 妹に宿題を手伝われました mà nên nói 妹に宿題を手伝ってもらいました vì đó là việc tích cực.' where id = '1f4a346c-9616-579e-b1d2-55ef70035bd6';
update grammar_points set extra_examples_jp = ARRAY['この小説は有名な作家によって書かれました。','万有引力の法則はニュートンによって発見されました。']::text[], extra_examples_vi = ARRAY['Cuốn tiểu thuyết này được viết bởi một nhà văn nổi tiếng.','Định luật vạn vật hấp dẫn được Newton phát hiện ra.']::text[], memory_tip = 'によって chuyên dùng cho TÁC PHẨM, PHÁT MINH, KHÁM PHÁ — nhớ đi kèm các động từ như 書かれる、発明される、発見される。', comparison_note = 'Khác N1は N2に + V bị động (dùng cho tác động cá nhân, đời thường) — によって trang trọng hơn, chỉ hợp với thành tựu lớn, có nguồn gốc rõ ràng.', common_mistake = 'Dùng によって cho hành động đời thường nhỏ (bị mắng, bị giẫm chân) — nghe rất kỳ, phải dùng に thay vì によって trong các trường hợp đó.' where id = '81bd8192-d3ab-53ce-b879-f6e8586e27e8';
update grammar_points set extra_examples_jp = ARRAY['私が一番好きなのは日本料理です。','毎朝走っているのは健康のためです。']::text[], extra_examples_vi = ARRAY['Món tôi thích nhất là ẩm thực Nhật Bản.','Việc mỗi sáng tôi chạy bộ là vì sức khỏe.']::text[], memory_tip = 'の biến cả một câu (thể thông thường) thành một cụm danh từ để làm chủ ngữ — nhớ như "cái việc mà..." đứng đầu câu.', comparison_note = 'Khác こと (cũng danh từ hoá nhưng trang trọng hơn, không dùng được với động từ tri giác như 見る、聞く) — の tự nhiên hơn trong khẩu ngữ.', common_mistake = 'Quên の, chỉ để nguyên mệnh đề thể thông thường trước はNです — câu sẽ sai ngữ pháp vì thiếu thành phần danh từ hoá chủ ngữ.' where id = '2ac8099a-6181-5f02-9a91-87cf3142bebb';
update grammar_points set extra_examples_jp = ARRAY['かぎをかけるのを忘れました。','友達に返信するのを忘れていました。']::text[], extra_examples_vi = ARRAY['Tôi quên khóa cửa.','Tôi đã quên nhắn tin trả lời bạn.']::text[], memory_tip = 'の biến động từ thành danh từ để làm tân ngữ cho 忘れました — nhớ luôn dùng thể từ điển + の trước を忘れました.', comparison_note = 'Khác Vるのを知っていますか (hỏi về sự biết) — 忘れました diễn tả QUÊN mất một việc cần làm, khác về nghĩa dù cùng cấu trúc の を + V.', common_mistake = 'Nhầm 忘れました (quên làm) với 忘れられません (không thể quên được, mang sắc thái khó quên kỷ niệm) — hai cấu trúc khác nghĩa hoàn toàn.' where id = '093620cc-433d-59b1-8fca-1b057f600095';
update grammar_points set extra_examples_jp = ARRAY['この店が来月閉店するのを知っていますか。','彼が引っ越したのを知りませんでした。']::text[], extra_examples_vi = ARRAY['Anh có biết cửa hàng này sẽ đóng cửa vào tháng sau không?','Tôi đã không biết là anh ấy đã chuyển nhà.']::text[], memory_tip = 'Nhớ phân biệt: 知りません (không biết, mãi mãi hoặc tính đến giờ) khác 知りませんでした (trước đó không biết, nhưng giờ vừa mới biết).', comparison_note = 'Khác V辞書形の を 忘れました (nói về việc quên làm) — cấu trúc này nói về việc BIẾT hay KHÔNG BIẾT một sự việc.', common_mistake = 'Dùng 知りません khi thực ra vừa mới biết tin đó (nên dùng 知りませんでした) — đây là lỗi rất phổ biến của người học vì tiếng Việt không phân biệt rõ hai thì này.' where id = 'a08c5285-9d76-5f9c-b6d6-d0a40929e607';
update grammar_points set extra_examples_jp = ARRAY['毎日日記を書くのは大変です。','外国語を話すのは楽しいです。']::text[], extra_examples_vi = ARRAY['Việc viết nhật ký mỗi ngày rất vất vả.','Nói ngoại ngữ là một việc thú vị.']::text[], memory_tip = 'のは biến hành động thành chủ đề của câu để đưa ra nhận xét — nhớ như "việc... thì..." trong tiếng Việt.', comparison_note = 'Khác Thể thông thường の は Nです (bổ ngữ là danh từ) — cấu trúc này bổ ngữ là TÍNH TỪ, dùng để nhận xét/đánh giá về hành động.', common_mistake = 'Quên biến tính từ な hoặc danh từ về đúng dạng khi nối câu — cần chú ý phần trước のは phải đúng thể thông thường, ví dụ 上手なのは chứ không phải 上手のは.' where id = '48cb531e-c77b-59af-be61-1672045dfe53';
update grammar_points set extra_examples_jp = ARRAY['困ったときの相談相手がいます。','旅行するときも、パスポートを忘れないでください。']::text[], extra_examples_vi = ARRAY['Tôi có người để tâm sự mỗi khi gặp khó khăn.','Kể cả khi đi du lịch cũng đừng quên hộ chiếu nhé.']::text[], memory_tip = 'とき là danh từ nên kết hợp linh hoạt với nhiều trợ từ: ときに (thời điểm cụ thể), ときの (bổ nghĩa cho danh từ), ときも (kể cả khi), ときや (liệt kê các thời điểm).', comparison_note = 'Khác あいだに (nhấn mạnh khoảng thời gian, một hành động xảy ra trong lúc hành động khác đang diễn ra) — とき chỉ đơn thuần nêu thời điểm, không nhấn khoảng thời gian kéo dài.', common_mistake = 'Dùng sai trợ từ sau とき, ví dụ dùng ときには khi ý muốn bổ nghĩa cho danh từ phía sau lẽ ra phải dùng ときの — cần chọn trợ từ theo đúng vai trò ngữ pháp trong câu.' where id = '0010e88a-9920-5fe4-942d-3b9d9c859064';
update grammar_points set extra_examples_jp = ARRAY['台風で飛行機が欠航になりました。','地震でたくさんの建物が壊れました。']::text[], extra_examples_vi = ARRAY['Vì bão nên chuyến bay đã bị hủy.','Vì động đất nên rất nhiều tòa nhà đã bị sập.']::text[], memory_tip = 'で ở đây chỉ NGUYÊN NHÂN khách quan, thường đi sau danh từ chỉ thiên tai/sự cố (台風、地震、事故、火事...).', comparison_note = 'Khác ので (nối cả một mệnh đề nguyên nhân, chủ quan hơn) — で chỉ nối trực tiếp SAU DANH TỪ, ngắn gọn hơn nhiều.', common_mistake = 'Dùng で cho nguyên nhân mang tính chủ ý của con người — で chỉ hợp với hiện tượng khách quan, không dùng khi vế sau là hành động có chủ ý của người nói.' where id = '1517f783-6665-5472-9c67-5192ebe5c609';
update grammar_points set extra_examples_jp = ARRAY['帰るとちゅうで、雨に降られました。','旅行のとちゅうで、財布をなくしてしまいました。']::text[], extra_examples_vi = ARRAY['Trên đường về, tôi bị dính mưa.','Giữa chuyến du lịch, tôi đã làm mất ví.']::text[], memory_tip = 'とちゅう nghĩa là "giữa chừng" — nhớ hình ảnh đang ở nửa đường, chưa đến đích thì có việc xảy ra.', comparison_note = 'Khác ながら (hai hành động cùng lúc do MỘT người chủ động thực hiện song song) — とちゅうで nói về một SỰ VIỆC BẤT NGỜ xảy ra giữa chừng một hành trình.', common_mistake = 'Dùng とちゅうで cho hai hành động chủ động làm song song — とちゅうで chuyên dùng khi có việc phát sinh NGOÀI Ý MUỐN giữa chừng một quá trình, không phải để nối hai hành động cố ý cùng lúc.' where id = '383bb304-e3cd-59a0-8de6-01efd6d54324';
update grammar_points set extra_examples_jp = ARRAY['明日試験があるので、今日は早く寝ます。','この部屋は静かなので、集中できます。']::text[], extra_examples_vi = ARRAY['Vì mai có kỳ thi nên hôm nay tôi sẽ ngủ sớm.','Vì phòng này yên tĩnh nên tôi có thể tập trung.']::text[], memory_tip = 'ので nghe nhẹ nhàng, khách quan hơn から — thường dùng khi giải thích lý do một cách lịch sự, ví dụ trong xin nghỉ, xin phép.', comparison_note = 'Khác から (mang tính chủ quan hơn, dùng được cả với mệnh lệnh/cấm đoán ở vế sau) — ので không hợp với mệnh lệnh, cấm đoán trực tiếp ở vế sau.', common_mistake = 'Quên đổi だ thành な trước ので với danh từ/tính từ な — phải nói 静かなので chứ không phải 静かだので.' where id = '9705d735-12b2-528a-8204-85f2537727af';
update grammar_points set extra_examples_jp = ARRAY['頭が痛くて、学校を休みました。','この町は静かで、住みやすいです。']::text[], extra_examples_vi = ARRAY['Vì đau đầu nên tôi đã nghỉ học.','Thị trấn này yên tĩnh nên rất dễ sống.']::text[], memory_tip = 'Đây chính là thể て/で đã học nhưng dùng để nối NGUYÊN NHÂN - KẾT QUẢ, kết quả thường liên quan cảm xúc/trạng thái/khả năng.', comparison_note = 'Khác から (nêu nguyên nhân rõ ràng, dùng được với mệnh lệnh/ý chí ở vế sau, và diễn tả trình tự thời gian rõ) — thể て/で không dùng được khi vế sau mang tính chủ ý mạnh.', common_mistake = 'Dùng thể て/で khi vế sau là mệnh lệnh hoặc lời mời — ví dụ không nói 疲れて、休んでください mà nên dùng 疲れたから、休んでください vì vế sau mang tính chủ ý.' where id = '0a050003-2565-587e-8b6b-e1e89c43e277';
update grammar_points set extra_examples_jp = ARRAY['この荷物はここに置いてもいいでしょうか。','明日は晴れるでしょうか。']::text[], extra_examples_vi = ARRAY['Không biết tôi để hành lý này ở đây có được không ạ?','Không biết ngày mai có nắng không nhỉ?']::text[], memory_tip = 'でしょうか lịch sự và nhẹ nhàng hơn か — dùng khi hỏi thăm dò ý kiến, xin phép một cách khiêm tốn.', comparison_note = 'Khác Thể thông thường + でしょう (câu khẳng định, đoán/suy luận, không phải câu hỏi trực tiếp) — でしょうか là dạng nghi vấn lịch sự của でしょう.', common_mistake = 'Dùng でしょうか trong tình huống cần câu trả lời chắc chắn, rõ ràng — でしょうか mang sắc thái dò hỏi, không hợp khi cần yêu cầu quyết đoán.' where id = 'ad41c647-34a6-5204-88d7-7e04849dda31';
update grammar_points set extra_examples_jp = ARRAY['彼が来るかどうか、まだ聞いていません。','この水が飲めるかどうか、確認してください。']::text[], extra_examples_vi = ARRAY['Tôi vẫn chưa hỏi xem anh ấy có đến hay không.','Hãy kiểm tra xem nước này có uống được hay không.']::text[], memory_tip = 'かどうか dùng cho câu hỏi CÓ/KHÔNG (không có từ nghi vấn) — nhớ như "có... hay không".', comparison_note = 'Khác Từ nghi vấn + Thể thông thường + か (dùng khi câu hỏi có từ nghi vấn như 何、いつ、どこ) — かどうか chỉ dùng cho câu hỏi nhị phân đúng/sai.', common_mistake = 'Thêm か vào sau かどうか (thừa) — chỉ cần かどうか là đủ, không cần かどうかか.' where id = 'c1604572-5e83-59da-a75b-54e78495dc9c';
update grammar_points set extra_examples_jp = ARRAY['この山は高さが3000メートル以上あります。','彼の優しさに感動しました。']::text[], extra_examples_vi = ARRAY['Ngọn núi này cao hơn 3000 mét.','Tôi đã rất cảm động trước sự tốt bụng của anh ấy.']::text[], memory_tip = 'さ biến tính từ thành danh từ chỉ MỨC ĐỘ/TÍNH CHẤT có thể đo đếm được — 高い→高さ (độ cao), 優しい→優しさ (sự tốt bụng).', comparison_note = 'Khác み (cũng danh từ hoá tính từ nhưng thiên về cảm nhận chủ quan, ví dụ 楽しみ, 悲しみ) — さ mang tính khách quan, đo lường được hơn.', common_mistake = 'Nhầm さ với み rồi dùng lẫn lộn — さ chủ yếu áp dụng cho tính từ đuôい, bỏ い rồi thêm さ, cần học thuộc riêng các từ hay dùng với み.' where id = '007f8a0e-0915-53de-85df-09f8d21c2498';
update grammar_points set extra_examples_jp = ARRAY['彼女がどこに住んでいるか、知りません。','何を食べたいか、教えてください。']::text[], extra_examples_vi = ARRAY['Tôi không biết cô ấy sống ở đâu.','Hãy cho tôi biết bạn muốn ăn gì.']::text[], memory_tip = 'Từ nghi vấn (どこ、何、いつ、だれ...) + thể thông thường + か = biến cả câu hỏi thành một cụm để lồng vào câu khác.', comparison_note = 'Khác Thể thông thường + かどうか (dùng cho câu hỏi có/không, không có từ nghi vấn) — cấu trúc này bắt buộc phải có từ nghi vấn.', common_mistake = 'Thêm か cho câu đã có かどうか, hoặc ngược lại thêm かどうか khi câu đã có từ nghi vấn riêng — chỉ chọn MỘT trong hai cách tùy có từ nghi vấn hay không.' where id = '09681c40-4425-5618-a35e-7ec81780729f';
update grammar_points set extra_examples_jp = ARRAY['新しい店ができたので、今度行ってみましょう。','分からない言葉は辞書で調べてみてください。']::text[], extra_examples_vi = ARRAY['Có một cửa hàng mới mở nên lần tới chúng ta thử đến xem sao.','Từ nào không hiểu thì hãy thử tra từ điển xem.']::text[], memory_tip = 'Nghĩ みます (thử) giống như "thử xem sao" trong tiếng Việt — làm rồi mới biết kết quả.', comparison_note = 'Khác Vて + おきます (chuẩn bị sẵn cho việc sau); Vて + みます nhấn mạnh hành động thử nghiệm, chưa biết kết quả.', common_mistake = 'Đừng dịch みます trong câu này là "nhìn" — khi đứng sau Vて, みます mất nghĩa gốc "nhìn", chỉ còn nghĩa "thử".' where id = 'd71c7ca9-7214-533d-98d8-85328b9b4ab8';
update grammar_points set extra_examples_jp = ARRAY['誕生日のプレゼントに時計を買いました。','記念に写真を撮りましょう。']::text[], extra_examples_vi = ARRAY['Tôi đã mua đồng hồ làm quà sinh nhật.','Hãy chụp ảnh để làm kỷ niệm nhé.']::text[], memory_tip = 'に ở đây trả lời câu hỏi "để làm gì, dùng vào việc gì" — gắn liền mục đích cụ thể của vật hoặc hành động.', comparison_note = 'Khác V辞書形の/N + に (mục đích sử dụng) — mẫu đó nói về công dụng của đồ vật, còn N+に+V này nói về mục đích tặng, làm ra một thứ gì đó.', common_mistake = 'Nhầm に chỉ mục đích tặng/làm với に chỉ thời gian hay địa điểm — ở đây に chỉ đứng sau danh từ mục đích (quà, kỷ niệm).' where id = '85292ed2-9958-59e2-9d1b-52ff34967991';
update grammar_points set extra_examples_jp = ARRAY['お手数ですが、資料を送ってくださいませんか。','少し静かにしてくださいませんか。']::text[], extra_examples_vi = ARRAY['Phiền anh chị một chút, anh chị có thể gửi tài liệu giúp tôi được không ạ?','Anh chị có thể yên lặng một chút được không ạ?']::text[], memory_tip = 'Câu càng dài (くださいませんか so với ください) thì càng lịch sự — thêm ませんか (phủ định nghi vấn) làm giọng điệu nhẹ nhàng, khiêm tốn hơn.', comparison_note = 'Lịch sự hơn Vて + くれませんか — dùng くださいませんか với người lớn tuổi, cấp trên hoặc người chưa quen biết.', common_mistake = 'Dùng くださいませんか với bạn bè thân thiết sẽ nghe quá trang trọng, xa cách; với bạn bè nên dùng ~てくれない?' where id = '6c81f1cb-60b4-584b-9d8b-31b2211e917a';
update grammar_points set extra_examples_jp = ARRAY['私は妹に英語を教えてやりました。','部長が空港まで送ってくださいました。']::text[], extra_examples_vi = ARRAY['Tôi đã dạy tiếng Anh cho em gái tôi.','Trưởng phòng đã đưa tôi ra sân bay.']::text[], memory_tip = 'やります cho người dưới hoặc con vật (làm ơn), いただきます là tôi được nhận ơn từ người trên (khiêm nhường), くださいます là người trên ban ơn cho tôi (kính trọng).', comparison_note = 'Khác あげます/もらいます/くれます ở mức độ lịch sự — bộ ba này là dạng kính ngữ, khiêm nhường ngữ tương ứng của あげます/もらいます/くれます.', common_mistake = 'Dùng やります cho người trên (ví dụ thầy giáo) là bất lịch sự — やります chỉ dùng cho người dưới, hậu bối, động thực vật.' where id = '747d7b23-1c75-5123-a284-95ef64c233c9';
update grammar_points set extra_examples_jp = ARRAY['私は友達に誕生日カードをあげました。','お客様から高級なワインをいただきました。']::text[], extra_examples_vi = ARRAY['Tôi đã tặng bạn thiệp chúc mừng sinh nhật.','Tôi đã được khách hàng tặng cho một chai rượu vang cao cấp.']::text[], memory_tip = 'Nhớ theo hướng: あげます là tôi cho đi (hướng ra ngoài), いただきます là tôi nhận vào (khiêm nhường), くださいます là người khác cho tôi (kính trọng, chủ ngữ không phải わたし).', comparison_note = 'Khác やります/さしあげます ở mức độ lịch sự trong nhóm cho (あげる) — さしあげます dùng khi tặng người có địa vị cao hơn nhiều.', common_mistake = 'Nhầm chủ ngữ của くださいます — chủ ngữ luôn là người khác (người cho), không bao giờ là わたし, vì đó là hành động của người khác dành cho mình.' where id = '7cf3fe50-d5b0-5a82-8c52-4e91082ab511';
update grammar_points set extra_examples_jp = ARRAY['この仕事を終わらせるには、3日はかかります。','引っ越しには10万円はかかります。']::text[], extra_examples_vi = ARRAY['Để hoàn thành công việc này, ít nhất cũng phải mất 3 ngày.','Chuyển nhà thì ít nhất cũng tốn 100 nghìn yên.']::text[], memory_tip = 'は sau lượng từ giống như nói "ít nhất là..." — đặt ra một mốc tối thiểu chắc chắn phải có.', comparison_note = 'Khác Lượng từ + も (nhiều đến mức) — も nhấn mạnh con số đó lớn, nhiều bất ngờ, còn は nhấn mạnh đó là mức tối thiểu cần có.', common_mistake = 'Nhầm は đứng sau lượng từ với は chủ đề thông thường — ở đây は chỉ nhấn mạnh mức tối thiểu, không tạo chủ đề mới cho câu.' where id = '625eca07-5b5d-56bc-b847-92ef44ef7d4e';
update grammar_points set extra_examples_jp = ARRAY['このレストランは3時間も待ちました。','彼はビールを10本も飲みました。']::text[], extra_examples_vi = ARRAY['Nhà hàng này tôi đã phải đợi đến tận 3 tiếng đồng hồ.','Anh ấy đã uống đến tận 10 chai bia.']::text[], memory_tip = 'も ở đây giống chữ "đến tận", "những" trong tiếng Việt — thể hiện sự ngạc nhiên vì con số quá lớn.', comparison_note = 'Khác Lượng từ + は (mức tối thiểu) — は nhấn mạnh mức tối thiểu cần có, còn も nhấn mạnh con số nhiều bất ngờ theo cảm nhận người nói.', common_mistake = 'Đừng nhầm も này với も nghĩa "cũng" đứng sau danh từ thường — も sau số lượng mang sắc thái cảm thán, không phải liệt kê.' where id = '10c50400-124d-57e0-9b7a-4d207d3ccf71';
update grammar_points set extra_examples_jp = ARRAY['家族のために、毎日一生懸命働いています。','日本の大学に入るために、日本語を勉強しています。']::text[], extra_examples_vi = ARRAY['Vì gia đình, tôi làm việc chăm chỉ mỗi ngày.','Để vào đại học ở Nhật, tôi đang học tiếng Nhật.']::text[], memory_tip = 'ため giống chữ "vì, để" — luôn đi với động từ có chủ ý, mục đích rõ ràng của người nói.', comparison_note = 'Khác V(khả năng/vô ý)辞書形/ない + ように — ように dùng khi động từ phía trước không mang tính chủ ý (khả năng, tự nhiên xảy ra), còn ために cần động từ chủ ý.', common_mistake = 'Dùng ために với động từ không chủ ý (như 分かる, できる) là sai — trường hợp đó phải dùng ように.' where id = 'b5698658-fc9c-51aa-9ad3-80aa1540401e';
update grammar_points set extra_examples_jp = ARRAY['週末、友達と映画を見に行きます。','忘れ物を取りに帰りました。']::text[], extra_examples_vi = ARRAY['Cuối tuần tôi sẽ đi xem phim với bạn.','Tôi đã về nhà để lấy đồ bỏ quên.']::text[], memory_tip = 'Bỏ ます của động từ rồi thêm に + đi/đến/về — giống công thức "đi LÀM GÌ" trong tiếng Việt.', comparison_note = 'Khác V辞書形の/N + に (mục đích sử dụng) — mẫu này chỉ mục đích của việc DI CHUYỂN, còn mẫu kia chỉ mục đích SỬ DỤNG một vật.', common_mistake = 'Quên đổi động từ về thể ます trước khi thêm に — không thể dùng thể từ điển hay thể て ở đây.' where id = '2626c1d8-4807-514b-a8be-a42539b85159';
update grammar_points set extra_examples_jp = ARRAY['この機械は野菜を洗うのに使います。','この辞書は漢字を調べるのに便利です。']::text[], extra_examples_vi = ARRAY['Cái máy này dùng để rửa rau.','Cuốn từ điển này tiện dụng để tra cứu chữ Hán.']::text[], memory_tip = 'Nhớ công thức: [Vる+の/N] + に + つかいます/べんりだ/やくにたつ/じかんがかかる — nói về công dụng, độ tiện lợi của vật.', comparison_note = 'Khác N + に + V (mục đích tặng, làm) — mẫu này nói công dụng của đồ vật, mẫu kia nói mục đích tặng, làm ra thứ gì đó.', common_mistake = 'Quên の sau động từ thể từ điển khi mục đích là một hành động (không phải danh từ) — ví dụ phải nói 切るのに chứ không phải 切るに.' where id = 'ff4acc57-2735-506f-8ef7-0babf3d088ec';
update grammar_points set extra_examples_jp = ARRAY['空が暗くなってきて、雨が降りそうです。','この問題は難しそうです。']::text[], extra_examples_vi = ARRAY['Trời tối sầm lại, có vẻ sắp mưa rồi.','Bài toán này trông có vẻ khó.']::text[], memory_tip = 'そう ở đây là "trông có vẻ" dựa trên những gì mắt nhìn thấy ngay lúc đó — khác với suy luận logic.', comparison_note = 'Khác Thể thông thường + そうです (nghe nói) — cùng chữ そうです nhưng cách nối khác nhau: thể ます/gốc tính từ + そう (vẻ ngoài) còn thể thông thường + そうです (nghe nói, truyền đạt lại).', common_mistake = 'Nhầm いい → いいそう (đúng phải là よさそう) và ない → なさそう — hai từ này là ngoại lệ khi chia そうです.' where id = '2ea0cf56-924d-5cf0-80a9-39d462426a29';
update grammar_points set extra_examples_jp = ARRAY['コンビニで飲み物を買ってきます。','郵便局へ手紙を出しに行ってきます。']::text[], extra_examples_vi = ARRAY['Tôi ra cửa hàng tiện lợi mua đồ uống rồi về.','Tôi ra bưu điện gửi thư rồi quay lại.']::text[], memory_tip = 'きます ở cuối câu này nghĩa là "rồi quay về (đây)" — hình dung một vòng đi, làm, về khép kín.', comparison_note = 'Khác V(ます) + に行きます/来ます/帰ります chỉ nói mục đích của việc đi mà không nhấn mạnh việc quay lại; てきます nhấn mạnh cả chuyến đi và quay về.', common_mistake = 'Nhầm てきます (đi rồi về) với てくる chỉ sự biến đổi, tiếp diễn dần dần (ví dụ 暗くなってきた) — cùng chữ nhưng hai cách dùng khác hẳn.' where id = 'cd0a4316-44e2-5d4b-ae1c-34d2036ffd68';
update grammar_points set extra_examples_jp = ARRAY['もっと大きく書いてください。','静かに話してください。']::text[], extra_examples_vi = ARRAY['Hãy viết to hơn một chút.','Hãy nói chuyện nhỏ nhẹ, yên tĩnh thôi.']::text[], memory_tip = 'Tính từ い đổi thành く, tính từ な đổi thành に — giống đuôi "-ly" biến tính từ thành trạng từ trong tiếng Anh.', comparison_note = 'Khác Adj/N + します (làm biến đổi) — mẫu này bổ nghĩa cho một động từ hành động cụ thể (cắt, viết, nói...), còn します diễn tả sự biến đổi trạng thái tổng quát.', common_mistake = 'Quên đổi tính từ な thành に (hay nhầm sang く) trước động từ — ví dụ phải nói 静かに話す chứ không phải 静かく話す.' where id = 'b8b3b66b-fa94-5fda-b4b6-76def8ef61f9';
update grammar_points set extra_examples_jp = ARRAY['エアコンをつけて、部屋を涼しくしました。','髪を短くしました。']::text[], extra_examples_vi = ARRAY['Tôi đã bật điều hòa cho phòng mát hơn.','Tôi đã cắt tóc ngắn đi.']::text[], memory_tip = 'します ở đây nghĩa là "làm cho trở nên..." — luôn có ai đó chủ động tạo ra sự thay đổi.', comparison_note = 'Khác Adj(く/に) + Động từ thường (bổ nghĩa cho một động từ hành động cụ thể); còn Adj/N+します chuyên dùng để diễn tả kết quả biến đổi trạng thái.', common_mistake = 'Nhầm với cách nói N/Adj + なります (tự nhiên trở nên) — します luôn có chủ thể chủ động tác động, còn なります là biến đổi tự nhiên, không cố ý.' where id = '80937d60-45e7-58cc-af27-bf7270c38d1d';
update grammar_points set extra_examples_jp = ARRAY['飲み物は何になさいますか。コーヒーにします。','旅行の行き先は北海道にしました。']::text[], extra_examples_vi = ARRAY['Quý khách dùng đồ uống gì ạ? Tôi chọn cà phê.','Tôi đã quyết định chọn Hokkaido làm điểm đến du lịch.']::text[], memory_tip = 'に trước します giống như "chốt" một lựa chọn trong nhiều phương án — chọn N này thay vì cái khác.', comparison_note = 'Khác Adj/N + します (làm biến đổi) — mẫu に+します chỉ dùng cho danh từ và mang nghĩa lựa chọn, quyết định, không phải biến đổi trạng thái.', common_mistake = 'Quên trợ từ に trước します khi diễn tả lựa chọn — thiếu に sẽ khiến câu tối nghĩa hoặc sai ngữ pháp.' where id = '145b17ac-2171-5629-b5b6-fccf5785aeb8';
update grammar_points set extra_examples_jp = ARRAY['このアプリは初心者には使いやすいです。','漢字は覚えにくいですが、面白いです。']::text[], extra_examples_vi = ARRAY['Ứng dụng này dễ sử dụng đối với người mới bắt đầu.','Chữ Hán khó nhớ nhưng thú vị.']::text[], memory_tip = 'やすい liên tưởng "dễ", にくい liên tưởng "khó, khó chịu" — ghép sau thân ます của động từ.', comparison_note = 'Khác V(ます)/Adj + すぎます (chỉ mức độ quá đà); やすい/にくい chỉ đánh giá độ dễ hay khó thực hiện, dễ hay khó xảy ra của một hành động.', common_mistake = 'Chia やすい/にくい như động từ (thêm ます) là sai — chúng chia giống tính từ đuôい (やすいです, やすかったです...).' where id = '276cfd88-6cc2-5ed8-a55d-89c671127ee0';
update grammar_points set extra_examples_jp = ARRAY['この問題は複雑すぎて、よく分かりません。','ゆうべ働きすぎて、体が痛いです。']::text[], extra_examples_vi = ARRAY['Vấn đề này quá phức tạp nên tôi không hiểu rõ lắm.','Tối qua tôi làm việc quá sức nên người đau nhức.']::text[], memory_tip = 'すぎます nghĩa gốc là "vượt qua" — ghép sau động từ, tính từ để nói "quá mức", "quá đà".', comparison_note = 'Khác V(ます) + やすい/にくいです (đánh giá độ dễ, khó); すぎます đánh giá mức độ vượt quá giới hạn hợp lý.', common_mistake = 'Nhầm cách ghép với tính từ な/い — tính từい bỏ い, tính từ な và danh từ giữ nguyên, đều thêm すぎます trực tiếp (không qua く/に).' where id = '31dda9d8-adaa-5c0b-a904-47ab4793875a';
update grammar_points set extra_examples_jp = ARRAY['頑張って勉強したのに、テストの点が悪かったです。','安いのに、あまり売れていません。']::text[], extra_examples_vi = ARRAY['Tôi đã cố gắng học vậy mà điểm bài kiểm tra vẫn kém.','Rẻ vậy mà lại không bán chạy mấy.']::text[], memory_tip = 'のに mang cảm xúc "ấm ức, bất ngờ" còn が/ても chỉ đơn thuần nối câu đối lập, không có cảm xúc.', comparison_note = 'Khác Thể thông thường + のに、~ (cách nối cụ thể); mục này so sánh sắc thái giữa のに và が/ても khi diễn đạt sự trái ngược.', common_mistake = 'Dùng のに khi chỉ muốn nói đối lập trung tính (không có cảm xúc) — trường hợp đó nên dùng が hoặc ても để tránh nghe như đang trách móc.' where id = '62a7bd56-b1f7-5118-a310-26939ceeb550';
update grammar_points set extra_examples_jp = ARRAY['もう4月なのに、まだ寒いです。','あんなに練習したのに、試合に負けてしまいました。']::text[], extra_examples_vi = ARRAY['Đã tháng 4 rồi vậy mà trời vẫn còn lạnh.','Đã luyện tập nhiều như vậy vậy mà vẫn thua trận đấu.']::text[], memory_tip = 'Nghe のに là nghĩ ngay đến vẻ mặt tiếc nuối, ấm ức — "vậy mà...", "thế mà...".', comparison_note = 'Khác Phân biệt のに và が/ても — mục này là cách chia cụ thể (danh từ, na-tính từ cần thêm な trước のに), còn mục kia so sánh sắc thái sử dụng.', common_mistake = 'Quên thêm な khi danh từ hoặc tính từ な đứng trước のに — ví dụ phải nói 上手なのに chứ không phải 上手のに.' where id = '65ab2f9d-6835-556f-b9a2-a0fba7a5e616';
update grammar_points set extra_examples_jp = ARRAY['台風で電車が止まった場合は、会社を休んでもいいです。','分からない場合は、いつでも聞いてください。']::text[], extra_examples_vi = ARRAY['Trong trường hợp tàu điện dừng vì bão, bạn được phép nghỉ làm.','Trường hợp không hiểu, bạn cứ hỏi bất cứ lúc nào.']::text[], memory_tip = 'ばあい là danh từ nghĩa "trường hợp" — nối với động từ, tính từ giống cách nối bổ nghĩa cho danh từ thông thường.', comparison_note = 'Khác cách dùng điều kiện thuần túy ば/と/たら; ばあい nhấn mạnh vào một tình huống cụ thể có thể xảy ra, thường dùng trong văn bản hướng dẫn, quy định.', common_mistake = 'Nhầm ばあい với điều kiện ば — ばあい là danh từ độc lập (trường hợp), không phải thể điều kiện ば của động từ.' where id = '62cd04ee-f6b5-52f8-b9ab-a07016a6d8aa';
update grammar_points set extra_examples_jp = ARRAY['日本語の勉強を始めたばかりで、まだ上手ではありません。','さっき昼ご飯を食べたばかりなので、お腹はすいていません。']::text[], extra_examples_vi = ARRAY['Tôi mới bắt đầu học tiếng Nhật nên chưa giỏi lắm.','Vì vừa mới ăn cơm trưa xong nên tôi chưa đói.']::text[], memory_tip = 'ばかり nghe giống "vừa mới... xong" — luôn đi với động từ thể た, nhấn mạnh khoảng cách thời gian còn rất gần.', comparison_note = 'Khác V辞書形/ている/た + ところです — たところ nhấn mạnh mốc thời gian vừa xong ngay lúc này, còn ばかり mang cảm nhận chủ quan, có thể là vài phút hay vài ngày trước.', common_mistake = 'Dùng ばかり với thể từ điển hoặc thể ている là sai — ばかり chỉ ghép sau động từ thể た.' where id = '6ca7fcc7-3b55-5af6-924e-dbd2133925d2';
update grammar_points set extra_examples_jp = ARRAY['ちょうど電車が出るところです。','今、資料を作っているところです。']::text[], extra_examples_vi = ARRAY['Ngay lúc này tàu điện sắp chạy.','Bây giờ tôi đang làm tài liệu.']::text[], memory_tip = 'ところ nghĩa gốc là "điểm, thời điểm" — ba dạng tương ứng với ba mốc: sắp làm, đang làm, vừa làm xong.', comparison_note = 'Khác Vた + ばかりです — Vたところです nhấn mạnh việc vừa xong ngay tức thì, còn ばかり có thể chỉ khoảng thời gian dài hơn theo cảm nhận chủ quan.', common_mistake = 'Nhầm ところ (điểm thời gian) với ばあい (trường hợp) — hai từ nghe gần giống về vị trí trong câu nhưng nghĩa hoàn toàn khác nhau.' where id = '70e0687e-3251-5945-9e76-4f01ba44052b';
update grammar_points set extra_examples_jp = ARRAY['田中さんはもう10年も日本語を勉強しているから、上手なはずです。','会議は3時からのはずですが、まだ始まっていません。']::text[], extra_examples_vi = ARRAY['Chị Tanaka đã học tiếng Nhật đến 10 năm rồi nên chắc chắn giỏi.','Cuộc họp đáng lẽ bắt đầu từ 3 giờ, nhưng vẫn chưa bắt đầu.']::text[], memory_tip = 'はず giống chữ "lẽ ra, chắc chắn phải" — người nói tin chắc dựa trên bằng chứng, không phải đoán mò.', comparison_note = 'Khác Thể thông thường + でしょう (suy đoán chung chung, ít chắc chắn); はず thể hiện độ tin cậy cao hơn vì dựa trên căn cứ cụ thể.', common_mistake = 'Dùng はずです cho suy đoán không có căn cứ rõ ràng — nếu chỉ là cảm tính thì nên dùng でしょう hoặc かもしれません thay vì はず.' where id = 'ed06007f-882c-5450-a6b4-afc778793474';
update grammar_points set extra_examples_jp = ARRAY['ニュースによると、来月から電気代が上がるそうです。','山田さんの話では、その店はもう閉まったそうです。']::text[], extra_examples_vi = ARRAY['Theo tin tức, nghe nói từ tháng sau giá điện sẽ tăng.','Theo lời anh Yamada, nghe nói cửa hàng đó đã đóng cửa rồi.']::text[], memory_tip = 'そうです (nghe nói) luôn gắn liền với một nguồn tin — báo, tin tức, lời ai đó kể lại, không phải tự mình quan sát.', comparison_note = 'Khác V(ます)/Adjそうです (vẻ ngoài, sắp) — cùng chữ そうです nhưng cách chia và nghĩa khác hẳn: đây là thể thông thường + そうです, mang nghĩa truyền đạt lại thông tin.', common_mistake = 'Nhầm với ようです (suy đoán từ giác quan) — そうです (nghe nói) không dựa trên quan sát cá nhân mà dựa hoàn toàn vào nguồn tin bên ngoài.' where id = '40fa221d-6a1c-5c29-8345-b1692ef09e72';
update grammar_points set extra_examples_jp = ARRAY['この道は雨で濡れている。さっき雨が降ったようです。','隣の部屋から音楽が聞こえる。誰かいるようです。']::text[], extra_examples_vi = ARRAY['Con đường này ướt vì mưa. Có vẻ như vừa nãy trời đã mưa.','Nghe có tiếng nhạc từ phòng bên cạnh. Hình như có ai đó ở trong.']::text[], memory_tip = 'ようです dựa vào những gì mắt thấy tai nghe ngay lúc đó để suy đoán — khác hẳn そうです chỉ dựa vào lời kể.', comparison_note = 'Khác Thể thông thường + そうです (nghe nói) — ようです là suy đoán chủ quan của người nói dựa trên giác quan, còn そうです chỉ truyền đạt lại nguồn tin từ người khác.', common_mistake = 'Danh từ, na-tính từ phải thêm の/な trước ようです (ví dụ 学生のようです, 元気なようです) — quên phần này là lỗi phổ biến.' where id = 'c0b4d757-e730-5317-8f8b-7712054dc9d6';
update grammar_points set extra_examples_jp = ARRAY['このコーヒーは苦い味がします。','台所からいいにおいがします。']::text[], extra_examples_vi = ARRAY['Ly cà phê này có vị đắng.','Có mùi thơm bay ra từ nhà bếp.']::text[], memory_tip = 'します ở đây nghĩa "cảm nhận thấy" — luôn đi với danh từ chỉ giác quan (tiếng, mùi, âm thanh, vị) + が.', comparison_note = 'Khác みえます/きこえます (nhìn thấy, nghe thấy một vật hoặc âm thanh cụ thể, có chủ thể rõ ràng); ~がします chỉ cảm giác chung chung lan tỏa trong không gian, không xác định nguồn.', common_mistake = 'Dùng trợ từ を thay vì が trước します — mẫu này luôn dùng が vì đó là hiện tượng tự nhiên xảy đến, không phải hành động chủ động.' where id = '4c8940ad-eb32-5ab4-bd68-23e7609be5a8';
update grammar_points set extra_examples_jp = ARRAY['先生は学生に漢字を書かせました。','母は私に野菜を食べさせました。']::text[], extra_examples_vi = ARRAY['Giáo viên đã bắt học sinh viết chữ Hán.','Mẹ đã bắt tôi ăn rau.']::text[], memory_tip = 'Có hai に trong câu sai khiến với tha động từ: に đầu chỉ người bị sai, を chỉ tân ngữ của hành động.', comparison_note = 'Khác Nを + Vさせます (sai khiến với tự động từ) — điểm khác biệt nằm ở trợ từ đánh dấu đối tượng bị sai khiến: に (khi có を khác trong câu) hay を (khi động từ không có tân ngữ riêng).', common_mistake = 'Dùng を cho cả người bị sai khiến lẫn tân ngữ khi động từ là tha động từ — sẽ gây trùng を trong câu, phải đổi người bị sai khiến sang に.' where id = '67e111e1-6f79-5093-be51-29254ad15959';
update grammar_points set extra_examples_jp = ARRAY['先生は学生を廊下に立たせました。','部長は新入社員を東京へ出張させました。']::text[], extra_examples_vi = ARRAY['Giáo viên đã bắt học sinh đứng ở hành lang.','Trưởng phòng đã cử nhân viên mới đi công tác Tokyo.']::text[], memory_tip = 'Vì tự động từ không có tân ngữ với を, nên trợ từ を được "nhường" lại để đánh dấu người bị sai khiến.', comparison_note = 'Khác Nに Nを + Vさせます (sai khiến với tha động từ) — khi động từ có tân ngữ riêng (tha động từ) thì người bị sai khiến phải chuyển sang に để tránh trùng を.', common_mistake = 'Dùng に cho người bị sai khiến ở tự động từ là sai — vì không có を nào khác trong câu nên phải dùng を cho người bị sai khiến.' where id = 'd5541e8d-4690-5626-a668-2152368591ed';
update grammar_points set extra_examples_jp = ARRAY['この仕事は私にやらせてください。','少し考えさせてください。']::text[], extra_examples_vi = ARRAY['Xin hãy để tôi làm công việc này.','Xin cho tôi suy nghĩ một chút.']::text[], memory_tip = 'させてください giống như "xin cho phép tôi được..." — người nói chủ động xin làm, không phải bị ép.', comparison_note = 'Khác Vさせます (thể sai khiến) thông thường — させてください chuyển vai: người nói xin phép được tự làm, không phải sai khiến người khác.', common_mistake = 'Nhầm させてください với ~てください thường — させてください luôn hàm ý xin phép làm gì đó vì lợi ích, mong muốn của người nói, không phải yêu cầu người khác làm.' where id = '83e3bfc2-2ac6-5a67-bdcf-08355ed9ce7d';
update grammar_points set extra_examples_jp = ARRAY['監督は選手たちに毎朝5キロ走らせます。','子供が習いたいと言ったので、ピアノを習わせました。']::text[], extra_examples_vi = ARRAY['Huấn luyện viên bắt các cầu thủ chạy 5 ki-lô-mét mỗi sáng.','Vì con nói muốn học nên tôi đã cho con học đàn piano.']::text[], memory_tip = 'させます mang hai nghĩa: bắt làm (cưỡng ép) hoặc cho phép làm (tùy ngữ cảnh và mối quan hệ trên dưới).', comparison_note = 'Khác Vさせられます (thể bị sai khiến) — させます là góc nhìn của người ra lệnh, còn させられます là góc nhìn của người bị bắt làm.', common_mistake = 'Nhầm quy tắc chia đuôi thể sai khiến giữa nhóm 1 và nhóm 2 — nhóm 1 đổi い→あ+せます (書く→書かせます), nhóm 2 bỏ る thêm させます (食べる→食べさせます).' where id = 'ca9e04fb-2450-57e2-bbcd-52a78bc0aad1';
update grammar_points set extra_examples_jp = ARRAY['上司に残業させられて、疲れました。','子供のころ、毎日ピアノを練習させられました。']::text[], extra_examples_vi = ARRAY['Tôi bị sếp bắt làm thêm giờ nên mệt mỏi.','Hồi nhỏ tôi bị bắt luyện đàn piano mỗi ngày.']::text[], memory_tip = 'させられます bằng させます (sai khiến) cộng られます (bị động) — ghép hai lớp nghĩa: bị người khác bắt làm.', comparison_note = 'Khác Vさせます (thể sai khiến) — させられます đảo ngược vai: chủ ngữ là người bị bắt làm, thường mang sắc thái miễn cưỡng, khó chịu.', common_mistake = 'Quên rút gọn động từ nhóm 1 kết thúc bằng す (như 話す) — thể bị sai khiến của 話す là 話させられる, nhiều người viết nhầm thành 話さされる.' where id = '241734b9-b050-5f91-9872-f9d23f3a7f11';
update grammar_points set extra_examples_jp = ARRAY['尊敬語は相手を高め、謙譲語は自分を低めます。','丁寧語はだれに対しても使えます。']::text[], extra_examples_vi = ARRAY['Tôn kính ngữ nâng cao đối phương, khiêm nhường ngữ hạ thấp bản thân.','Thể lịch sự có thể dùng với bất kỳ ai.']::text[], memory_tip = 'Nhớ ba hướng: そんけいご nâng người khác lên, けんじょうご hạ mình xuống, ていねいご chỉ đơn thuần lịch sự, không nâng hay hạ ai.', comparison_note = 'Khác Tôn kính ngữ (尊敬語) và Khiêm nhường ngữ お/ご + V(ます) + します — đây là mục tổng quan phân loại, hai mục kia đi sâu vào từng loại cụ thể.', common_mistake = 'Dùng nhầm khiêm nhường ngữ cho hành động của người khác (hoặc tôn kính ngữ cho hành động của mình) — hai loại này không thể hoán đổi cho nhau.' where id = 'be1645b3-1a8a-5f7e-8743-9917ec2dbb4b';
update grammar_points set extra_examples_jp = ARRAY['会社の外の人には、自分の上司にも敬語を使いません。','初めて会う人には敬語を使うのが普通です。']::text[], extra_examples_vi = ARRAY['Với người ngoài công ty, ngay cả nói về cấp trên của mình cũng không dùng kính ngữ.','Với người mới gặp lần đầu, dùng kính ngữ là điều bình thường.']::text[], memory_tip = 'Nhớ quy tắc うち・そと (trong, ngoài): với người ngoài nhóm, người trong nhóm mình (kể cả sếp) không được dùng kính ngữ.', comparison_note = 'Khác Tính nhất quán khi dùng kính ngữ — mục này nói khi nào nên dùng kính ngữ, mục kia nói cách dùng sao cho đồng bộ trong cùng một câu.', common_mistake = 'Dùng kính ngữ cho sếp của mình khi nói chuyện với khách hàng, đối tác bên ngoài — đây là lỗi phổ biến của người mới học, vì tiếng Việt không có quy tắc trong ngoài này.' where id = 'dba87dad-fb6d-513f-aa85-473d44aac9e3';
update grammar_points set extra_examples_jp = ARRAY['先生はもう帰られた?','部長、あしたいらっしゃる?']::text[], extra_examples_vi = ARRAY['Thầy đã về chưa vậy?','Trưởng phòng, mai anh có đến không ạ?']::text[], memory_tip = 'Bỏ です/ます ở cuối câu kính ngữ nhưng vẫn giữ động từ kính ngữ — vừa thân mật vừa vẫn tôn trọng.', comparison_note = 'Khác Kính ngữ - tổng quan (dùng đầy đủ です/ます) — mẫu này thường dùng khi hỏi han thân mật về người cần tôn trọng, với người nghe là bạn bè, người thân.', common_mistake = 'Dùng cách nói này trực tiếp với người cần tôn trọng — mẫu này chỉ dùng khi nói về người đó với người thứ ba thân thiết, không dùng khi nói thẳng với người cần kính trọng.' where id = 'e25300c5-b5aa-5887-bf65-bfdd0c516ddd';
update grammar_points set extra_examples_jp = ARRAY['先生のお子さんも今度の旅行にいらっしゃいますか。','社長のお荷物はこちらでお預かりします。']::text[], extra_examples_vi = ARRAY['Con của thầy có đi cùng chuyến du lịch lần này không ạ?','Hành lý của giám đốc, xin để chúng tôi giữ giúp ạ.']::text[], memory_tip = 'Một khi đã "bật chế độ" kính ngữ cho câu, hãy giữ nó xuyên suốt — cả danh từ lẫn động từ liên quan đến người đó.', comparison_note = 'Khác Kính ngữ - tổng quan (khi nào dùng kính ngữ) — mục này tập trung vào việc dùng đồng bộ, tránh pha trộn kính ngữ nửa vời trong cùng một câu.', common_mistake = 'Chỉ tôn kính hóa động từ chính mà quên các danh từ liên quan (お+danh từ) — ví dụ nói 部長の家 thay vì お宅 khi đang dùng kính ngữ cho cả câu.' where id = '858c6a73-40e3-5ef4-898c-d50f3e8112ef';
update grammar_points set extra_examples_jp = ARRAY['校長先生が式でお話しになりました。','どうぞ、こちらの席にお座りください。']::text[], extra_examples_vi = ARRAY['Thầy hiệu trưởng đã phát biểu tại buổi lễ.','Xin mời ngồi vào ghế này ạ.']::text[], memory_tip = '尊敬語 dùng để nâng hành động của người khác lên — nhớ nhóm động từ đặc biệt: いらっしゃる (đi, đến, ở), めしあがる (ăn), おっしゃる (nói).', comparison_note = 'Khác Khiêm nhường ngữ お/ご + V(ます) + します — tôn kính ngữ nâng người khác, khiêm nhường ngữ hạ thấp bản thân, hai hướng ngược nhau hoàn toàn.', common_mistake = 'Dùng tôn kính ngữ cho chính hành động của bản thân — ví dụ tự nói 私がいらっしゃいます là sai, vì tôn kính ngữ chỉ dùng cho người khác.' where id = '0d039701-78dc-5a6f-bb27-b47eec3dbe00';
update grammar_points set extra_examples_jp = ARRAY['昨日は会議に遅れまして、申し訳ございませんでした。','資料を拝見しまして、大変勉強になりました。']::text[], extra_examples_vi = ARRAY['Hôm qua tôi đã đến trễ cuộc họp, thành thật xin lỗi.','Sau khi xem qua tài liệu, tôi đã học hỏi được rất nhiều.']::text[], memory_tip = 'まして là dạng trang trọng của て — dùng khi cần nối câu trong văn phong lịch sự, trịnh trọng (xin lỗi, phát biểu trang trọng).', comparison_note = 'Khác Thể lịch sự (丁寧語) nói chung — Vまして chỉ áp dụng riêng cho cách nối thể て sang trang trọng hơn, không phải mọi trường hợp lịch sự.', common_mistake = 'Lạm dụng まして trong giao tiếp thường ngày với bạn bè — cách nói này chỉ hợp trong ngữ cảnh trang trọng như công việc, phát biểu, xin lỗi chính thức.' where id = 'f8e657fb-ef0e-5c58-9dcb-891edc2a7ef8';
update grammar_points set extra_examples_jp = ARRAY['荷物はこちらでお預かりします。','詳しい内容は後ほどご説明します。']::text[], extra_examples_vi = ARRAY['Hành lý xin để chúng tôi giữ giúp ạ.','Nội dung chi tiết tôi sẽ giải thích sau ạ.']::text[], memory_tip = 'お/ご+V(ます)+します nghĩa là tôi hạ mình làm gì đó cho người nghe — nhớ động từ nhóm 3 gốc Hán dùng ご, còn lại dùng お.', comparison_note = 'Khác Tôn kính ngữ (尊敬語) — khiêm nhường ngữ hạ thấp hành động của mình để gián tiếp tôn trọng người nghe, ngược hướng với tôn kính ngữ.', common_mistake = 'Dùng お/ご+V+します cho hành động của người khác — mẫu này chỉ dùng cho hành động của bản thân người nói hướng tới người nghe.' where id = 'a295623a-8301-5bb7-8f86-0e1b93475dd2';
update grammar_points set extra_examples_jp = ARRAY['こちらにお名前とご住所をお書きください。','ただいま担当者がまいります。']::text[], extra_examples_vi = ARRAY['Xin quý khách ghi họ tên và địa chỉ vào đây ạ.','Nhân viên phụ trách sẽ đến ngay ạ.']::text[], memory_tip = '丁寧語 là lớp lịch sự nền tảng, áp dụng chung cho mọi đối tượng — không nâng ai lên hay hạ ai xuống, chỉ đơn thuần thể hiện sự lễ phép.', comparison_note = 'Khác Tôn kính ngữ và Khiêm nhường ngữ — 丁寧語 là lớp lịch sự cơ bản nhất (です/ます, ございます), còn hai loại kia thêm sắc thái nâng, hạ vai vế.', common_mistake = 'Nhầm 丁寧語 với 尊敬語 — 丁寧語 chỉ lịch sự về hình thức câu nói, không phụ thuộc vào việc nói về ai, khác với tôn kính ngữ vốn gắn với đối tượng cụ thể.' where id = 'aac16e81-525c-5b3c-8d42-b7bb275ac760';

-- comparison pairs (SO SÁNH VỚI)
